export const READING = {
  1: [
    { topic: "Checkpoint procedures", passage: "Corporal Davies is on duty at Checkpoint Alpha. He stops a civilian vehicle and asks the driver to show identification. The driver presents a passport. The corporal checks the document and records the entry time as 0820. He then waves the vehicle through.", question: "What time did the vehicle pass through the checkpoint?", options: ["0820", "0800", "0830", "0840"], answer: 0, ex: "The entry time is explicitly stated as 0820. Level 1 Reading tests ability to find specific facts in short texts (~50 words)." },
    { topic: "Daily military routine", passage: "The morning briefing begins at 0700. All officers must be present. Sergeant Major Rodriguez will present the daily schedule. After the briefing, personnel will proceed to their assigned posts. Breakfast is available in the mess hall until 0630.", question: "When does the morning briefing start?", options: ["0600", "0700", "0630", "0800"], answer: 1, ex: "'The morning briefing begins at 0700.' Note that breakfast ends BEFORE the briefing — a common Level 1 trap testing careful reading." },
    { topic: "Equipment and supplies", passage: "The supply depot received a shipment of 200 ration packs, 50 first aid kits, and 30 radio batteries. The items were checked and stored. The depot commander signed the delivery receipt at 1400.", question: "How many first aid kits were received?", options: ["200", "30", "50", "100"], answer: 2, ex: "'50 first aid kits' — Level 1 tests precise number retrieval. Don't confuse with 200 (ration packs) or 30 (batteries)." },
    { topic: "Medical — first aid", passage: "Private Johnson was injured during training. He reported to the medical centre at 1530. The medic treated a cut on his left hand. Johnson was cleared to return to duty the following morning.", question: "Which part of Private Johnson's body was injured?", options: ["Right hand", "Left arm", "Right arm", "Left hand"], answer: 3, ex: "'A cut on his left hand' — small details like left vs right are commonly tested at Level 1." },
    { topic: "Weather report", passage: "Tomorrow's weather forecast: cloudy in the morning with light rain expected after 1100. Temperature will reach 18 degrees Celsius. Wind from the west at 15 kilometres per hour. Visibility good. The weather may affect afternoon training activities.", question: "When is rain expected to begin?", options: ["After 1100", "In the early morning", "In the evening", "At midnight"], answer: 0, ex: "'Light rain expected after 1100' — straightforward time retrieval. 'After 1100' means from 1100 onwards." },
    { topic: "Personnel announcement", passage: "Lieutenant Smith has been promoted to the rank of Captain. The promotion ceremony will take place on Friday at 1000 in the parade ground. All officers are invited to attend. Dress uniform is required.", question: "What rank has Lieutenant Smith been promoted to?", options: ["Major", "Captain", "Colonel", "Sergeant"], answer: 1, ex: "'Promoted to the rank of Captain' — direct fact retrieval. Don't be distracted by the original rank (Lieutenant)." },
    { topic: "Training schedule", passage: "The new recruits will begin physical training at 0500 daily. The training session lasts two hours. Breakfast follows at 0730. Weapon training starts at 0900 and continues until lunch.", question: "How long is the morning physical training session?", options: ["One hour", "Three hours", "Two hours", "Half an hour"], answer: 2, ex: "'The training session lasts two hours' — direct fact retrieval. Note that 0500–0700 = 2 hours, then breakfast at 0730." },
    { topic: "Vehicle inspection", passage: "All military vehicles must undergo daily inspection before use. Drivers check fuel levels, tyre pressure, oil, and lights. Any faults must be reported to the motor sergeant immediately. Inspection takes about ten minutes.", question: "Who must drivers report faults to?", options: ["The platoon commander", "The duty officer", "The base commander", "The motor sergeant"], answer: 3, ex: "'Any faults must be reported to the motor sergeant immediately' — specific role identification at Level 1." },
    { topic: "Mess hall information", passage: "The mess hall serves three meals per day. Breakfast is from 0600 to 0700. Lunch is from 1200 to 1330. Dinner is from 1800 to 1900. Hot drinks are available all day from the coffee machine.", question: "Until what time is lunch served?", options: ["1330", "1200", "1300", "1400"], answer: 0, ex: "'Lunch is from 1200 to 1330' — pay attention to start vs end time. 1330 is the closing time." },
    { topic: "Guard duty roster", passage: "Private Williams is assigned to guard duty tonight. His shift begins at 2200 and ends at 0200. He will be at Gate Two. Corporal Brown will relieve him. Williams must arrive ten minutes early.", question: "Where will Private Williams be on guard duty?", options: ["Gate One", "Gate Two", "Gate Three", "The main entrance"], answer: 1, ex: "'He will be at Gate Two' — location retrieval. Don't confuse with the relieving guard (Corporal Brown)." },
    { topic: "Checkpoint Procedure", passage: "All personnel approaching Checkpoint Bravo must present identification cards to the guard on duty. Vehicles must stop ten meters before the barrier. The guard will inspect the vehicle and verify the driver's ID. Only after clearance will the barrier be raised. The checkpoint operates 24 hours.", question: "How far before the barrier must vehicles stop?", options: ["Five meters", "Fifteen meters", "Ten meters", "Twenty meters"], answer: 2, ex: "本文に 'Vehicles must stop ten meters before the barrier' と明記されている。L1 は事実検索レベルで、本文の数値をそのまま照合する。" },
    { topic: "Supply List", passage: "The unit received the following supplies this morning: 200 rations, 50 blankets, 30 medical kits, and 100 liters of fresh water. The commanding officer signed for delivery at 0800 hours. All items were stored in Warehouse C under Sergeant Miller.", question: "How many medical kits were delivered?", options: ["20", "50", "100", "30"], answer: 3, ex: "本文に '30 medical kits' とあり、数値を直接抽出する典型的な L1 問題。他の数値はそれぞれ別のアイテムに対応している distractor。" },
    { topic: "Daily Training Plan", passage: "Tomorrow's training schedule is as follows: 0600 physical training, 0800 weapons handling, 1000 first aid, 1300 map reading, and 1500 radio communications. Lunch is served between 1200 and 1300 in the main mess hall.", question: "What activity takes place at 1000?", options: ["First aid", "Weapons handling", "Map reading", "Radio communications"], answer: 0, ex: "'1000 first aid' という直接記載から答えを抽出。時刻と活動内容の対応を問う基本的な事実検索問題。" },
    { topic: "Weekly Duty Assignment", passage: "The guard duty roster for this week is posted on the bulletin board. Corporal Smith will be on duty Monday, Private Jones on Tuesday, Sergeant Brown on Wednesday, and Lieutenant Davis on Thursday. Friday's duty is shared between two soldiers.", question: "Who is on guard duty on Wednesday?", options: ["Corporal Smith", "Sergeant Brown", "Private Jones", "Lieutenant Davis"], answer: 1, ex: "'Sergeant Brown on Wednesday' という直接記述から答えを特定する。曜日と人名の対応を問う L1 レベルの問題。" },
    { topic: "Quartermaster Stores Hours", passage: "The quartermaster stores are open Monday through Friday from 0900 to 1500. They are closed for stocktaking between 1200 and 1300. Items must be requested using form Q-7. The stores manager is Sergeant Hill, and emergency requests outside opening hours require approval from the duty officer.", question: "When are the stores closed during the day?", options: ["0900 to 1200", "1300 to 1500", "1200 to 1300", "All afternoon"], answer: 2, ex: "本文 'closed for stocktaking between 1200 and 1300' から、お昼の1時間が休止時間。L1 の時刻範囲読み取り問題で、開店時間 (0900-1500) と中断時間を区別する。" },
    { topic: "Vehicle Maintenance", passage: "Vehicle 47 requires maintenance every 5,000 kilometers. The last service was performed at 32,000 km. The vehicle is currently at 36,500 km. Maintenance includes oil change, filter replacement, and tire inspection. The maintenance log is kept in the motor pool office.", question: "At what mileage was the last service performed?", options: ["5,000 km", "36,500 km", "37,000 km", "32,000 km"], answer: 3, ex: "'The last service was performed at 32,000 km' という直接記述から数値を抽出する事実検索問題。" },
    { topic: "Radio Frequencies", passage: "The primary frequency for company communications is 145.500 MHz. The secondary frequency is 146.200 MHz. The emergency frequency is 121.500 MHz. All radio operators must memorize these three frequencies before deployment to the field.", question: "What is the emergency frequency?", options: ["121.500 MHz", "145.500 MHz", "146.200 MHz", "150.000 MHz"], answer: 0, ex: "本文に 'The emergency frequency is 121.500 MHz' と明記。複数の数値情報の中から特定のものを抽出する基本問題。" },
    { topic: "Unit Strength", passage: "Alpha Company currently has 120 soldiers on active duty. There are 4 officers, 16 non-commissioned officers, and 100 enlisted personnel. Five soldiers are on medical leave and three are attending courses abroad.", question: "How many non-commissioned officers are in Alpha Company?", options: ["4", "16", "100", "120"], answer: 1, ex: "'16 non-commissioned officers' という直接記述から数値を抽出する。複数の数値の中から正しい区分を選ぶ L1 問題。" },
    { topic: "Field Exercise Location", passage: "The annual field exercise will take place at Camp Eagle, located 80 kilometers north of headquarters. Units will deploy by road convoy on Monday at 0500 hours. The exercise will last seven days and involve three battalions.", question: "Where will the field exercise take place?", options: ["Camp Bravo", "Camp Falcon", "Camp Eagle", "Headquarters"], answer: 2, ex: "'The annual field exercise will take place at Camp Eagle' という直接記述から場所を特定する。L1 の典型的な固有名詞検索問題。" },
    { topic: "Medical Inventory", passage: "The field hospital reports the following inventory: 500 bandages, 200 syringes, 150 doses of antibiotics, and 80 units of blood plasma. Additional supplies are expected next Tuesday. All items must be checked against the master list every Monday.", question: "How many doses of antibiotics are in the inventory?", options: ["80", "200", "500", "150"], answer: 3, ex: "'150 doses of antibiotics' という直接記述から数値を抽出。複数の数値情報の中から特定品目を識別する L1 問題。" },
    { topic: "Ammunition Storage", passage: "The ammunition depot stores four types of ordnance: small arms ammunition in Building A, grenades in Building B, mortar rounds in Building C, and anti-tank missiles in Building D. Each building has its own security officer. Access to Building D requires special authorization from the battalion commander.", question: "Where are the grenades stored?", options: ["Building B", "Building A", "Building C", "Building D"], answer: 0, ex: "'grenades in Building B' という直接対応から答えを特定する。L1 は複数の対応関係から正しいペアを識別する能力を問う。" },
    { topic: "Communication Protocol", passage: "Radio callsigns are assigned as follows: Command post is Alpha One, first platoon is Bravo Two, second platoon is Charlie Three, and support element is Delta Four. All transmissions must begin with the recipient's callsign followed by the sender's callsign.", question: "What is the callsign for the command post?", options: ["Bravo Two", "Alpha One", "Charlie Three", "Delta Four"], answer: 1, ex: "'Command post is Alpha One' という直接記述から答えを抽出。コールサインと部隊の対応を問う典型的な L1 問題。" },
    { topic: "Equipment Issue", passage: "Each soldier is issued the following items: one helmet, two uniforms, one pair of boots, three pairs of socks, and one sleeping bag. Damaged items can be exchanged at the supply room on weekdays between 0900 and 1600. Lost items must be reported to the company clerk.", question: "How many uniforms is each soldier issued?", options: ["One", "Three", "Two", "Four"], answer: 2, ex: "'two uniforms' という数値の直接抽出。複数のアイテムと数量の中から正しい対応を識別する L1 問題。" },
    { topic: "Patrol Route", passage: "Today's patrol route begins at the main gate, proceeds north to the bridge, turns east along the river, continues south to the market, and returns west to the main gate. The patrol departs at 0700 and is expected to return by 1100. Three soldiers will conduct the patrol.", question: "In which direction does the patrol turn after reaching the bridge?", options: ["North", "South", "West", "East"], answer: 3, ex: "'turns east along the river' という記述から方向を特定。経路の方向転換を問う L1 の地理的理解問題。" },
    { topic: "Inspection Schedule", passage: "Weekly inspections are conducted as follows: weapons on Monday, vehicles on Tuesday, barracks on Wednesday, equipment on Thursday, and uniforms on Friday. All inspections begin at 0900 sharp. Personnel must be present at their assigned locations ten minutes early.", question: "On which day are vehicles inspected?", options: ["Tuesday", "Monday", "Wednesday", "Thursday"], answer: 0, ex: "'vehicles on Tuesday' という直接対応から答えを抽出。曜日と活動の対応を問う典型的な L1 問題。" },
    { topic: "Range Safety Rules", passage: "The firing range has three safety zones marked by colored flags. The red zone extends 50 meters from the firing line, the yellow zone extends from 50 to 100 meters, and the green zone is beyond 100 meters. Only personnel with hearing protection may enter the red zone when firing is in progress.", question: "How far does the red zone extend from the firing line?", options: ["25 meters", "50 meters", "75 meters", "100 meters"], answer: 1, ex: "'red zone extends 50 meters from the firing line' という数値の直接抽出。距離と安全ゾーンの対応を問う L1 問題。" },
    { topic: "Duty Hours", passage: "The operations center is staffed in three shifts. The day shift works from 0800 to 1600, the evening shift from 1600 to 2400, and the night shift from 2400 to 0800. Each shift has four personnel on duty. The shift supervisor prepares a handover report at the end of each shift.", question: "When does the evening shift begin?", options: ["0800", "1200", "1600", "2400"], answer: 2, ex: "'evening shift from 1600 to 2400' という時刻の直接抽出。シフト時間を問う基本的な L1 問題。" },
    { topic: "Personnel Count", passage: "The convoy consists of five vehicles. Vehicle One carries the commander and three staff officers. Vehicle Two carries eight infantry soldiers. Vehicle Three carries six engineers. Vehicle Four carries medical personnel and supplies. Vehicle Five carries communications equipment and two operators.", question: "How many engineers are in the convoy?", options: ["Three", "Eight", "Ten", "Six"], answer: 3, ex: "'Vehicle Three carries six engineers' という直接記述から数を抽出。複数の車両と人員数の中から正しい対応を識別する L1 問題。" },
    { topic: "Storage Temperature", passage: "Different types of supplies require different storage conditions. Food rations must be stored at room temperature, vaccines at 2 to 8 degrees Celsius, blood products at minus 20 degrees Celsius, and explosives in a cool dry place below 25 degrees Celsius. Temperature is monitored continuously.", question: "At what temperature should vaccines be stored?", options: ["2 to 8 degrees Celsius", "Room temperature", "Below 25 degrees Celsius", "Minus 20 degrees Celsius"], answer: 0, ex: "'vaccines at 2 to 8 degrees Celsius' という直接対応から答えを特定。品目と保管温度の対応を問う L1 問題。" },
    { topic: "Meeting Location", passage: "This week's briefings will be held in different locations. Monday's briefing is in Conference Room A on the second floor. Tuesday's briefing is in the main auditorium. Wednesday's briefing is in the training hall. Thursday and Friday briefings return to Conference Room A.", question: "Where is Tuesday's briefing held?", options: ["Conference Room A", "Main auditorium", "Training hall", "Second floor"], answer: 1, ex: "'Tuesday's briefing is in the main auditorium' という直接記述から場所を特定。曜日と場所の対応を問う典型的な L1 問題。" },
    { topic: "Library opening notice", passage: "The unit library is open Monday to Friday from 0900 to 1800. Saturday opening hours are 0900 to 1300. The library is closed on Sundays and public holidays. Books may be borrowed for two weeks. Late returns incur a small fine.", question: "How long can books be borrowed for?", options: ["One week", "One month", "Two weeks", "Until the next holiday"], answer: 2, ex: "本文 'Books may be borrowed for two weeks' を直接抽出。L1 の事実検索問題で、開館時間 (0900-1800) などの distractor に惑わされず貸出期間を見つける。" },
    { topic: "Vehicle parking notice", passage: "Parking on Camp Bravo is restricted to authorised vehicles only. Visitors must park in Visitor Lot A near the main gate. Long-term parking is in Lot B behind the headquarters building. Vehicles parked in unauthorised areas will be towed at the owner's expense.", question: "Where should visitors park?", options: ["Lot B", "Behind the headquarters", "Anywhere on the camp", "Visitor Lot A"], answer: 3, ex: "本文 'Visitors must park in Visitor Lot A near the main gate' から訪問者用駐車場を識別。Lot B は long-term 用なので distractor。L1 の場所識別問題。" },
    { topic: "Lost and found notice", passage: "Notice. A black wallet was found in the gymnasium yesterday. The owner can collect it from the security desk between 0800 and 1700. Identification is required. Unclaimed items will be held for 30 days before disposal.", question: "What was found?", options: ["A black wallet", "A blue wallet", "A wallet and keys", "A small bag"], answer: 0, ex: "本文 'A black wallet was found' から色とアイテム種別を抽出。distractor は色違いや別アイテムを混入する典型的な L1 事実検索問題。" },
    { topic: "Station ticket office hours", passage: "The station ticket office is open from 0530 to 2200 daily. Tickets to nearby cities can be purchased here. For long-distance journeys, please use the automated machines or the online booking system. Cash and credit cards are accepted at the counter.", question: "How can passengers buy long-distance tickets?", options: ["At the ticket counter", "Using machines or online", "Only with cash", "On the train itself"], answer: 1, ex: "本文 'For long-distance journeys, please use the automated machines or the online booking system' から、長距離チケットは機械かオンラインで購入。窓口は近距離用。L1 の用途別案内識別問題。" },
    { topic: "Annual health check notice", passage: "Notice from the medical centre. Annual health checks for personnel born in March will be conducted next week. Please report to the medical centre at your assigned time. Bring your military ID and medical record book. Fasting for 12 hours before the appointment is required.", question: "What must personnel bring to the appointment?", options: ["Only their ID card", "Just the record book", "ID and medical record book", "Nothing is required"], answer: 2, ex: "本文 'Bring your military ID and medical record book' から両方が必要。fasting (絶食) の指示に注意を逸らされないよう、'bring' の対象だけを抽出する L1 持参物識別問題。" }
  ],
  2: [
    { topic: "Rules of engagement — Kosovo", passage: "KFOR troops deployed in Kosovo operate under strict rules of engagement. Soldiers are authorised to use force only in self-defence or to protect civilians under imminent threat. Any use of force must be reported immediately to the commanding officer and documented in the duty log. Troops are reminded that all actions must comply with international humanitarian law.", question: "Under what circumstances may KFOR soldiers use force?", options: ["At any time they consider operationally necessary for mission accomplishment in theatre", "Only in self-defence or to protect civilians under imminent threat", "Only after receiving prior written authorisation from their immediate commander", "Only when explicitly ordered to do so by a superior officer through formal channels"], answer: 1, ex: "'Authorised to use force only in self-defence or to protect civilians under imminent threat' — Level 2 tests understanding of conditions and restrictions, not just isolated facts." },
    { topic: "Convoy logistics", passage: "The logistics convoy departed Camp Bravo at 0530 and was scheduled to arrive at Forward Operating Base Delta by 1100. Due to a road obstruction caused by a landslide, the convoy was forced to take an alternative route, adding approximately 45 minutes to the journey. The convoy commander reported the delay to headquarters and requested updated arrival time confirmation.", question: "What caused the convoy's delay?", options: ["A vehicle breakdown", "Enemy activity on the main road", "A landslide blocking the road", "Bad weather conditions"], answer: 2, ex: "'A road obstruction caused by a landslide' — paraphrase comprehension: the question asks for the cause, not the route change." },
    { topic: "Humanitarian medical support", passage: "NATO medical teams established a field hospital near the town of Brcko to support the local civilian population affected by flooding. The facility treated over 300 patients in the first 48 hours. Medical staff worked in 12-hour shifts to maintain continuous coverage. Supplies were replenished daily by helicopter, as road access remained limited due to flood damage.", question: "Why were supplies delivered by helicopter?", options: ["It was faster than road transport", "The roads were controlled by hostile forces", "Helicopter transport was cheaper", "Road access was limited due to flood damage"], answer: 3, ex: "'Supplies were replenished daily by helicopter, as road access remained limited due to flood damage' — 'as' = because." },
    { topic: "Training exercise overview", passage: "Exercise NORTHERN STAR is a multinational training exercise scheduled to take place over two weeks in northern Norway. Participating nations include Norway, the United Kingdom, Canada, and Italy. The exercise will focus on cold-weather operations and interoperability between national forces. Approximately 4,000 personnel will take part. Live-fire training will be conducted only at designated ranges.", question: "What is the main focus of the exercise?", options: ["Cold-weather operations and interoperability", "Live-fire testing of newly fielded combat equipment", "Basic training for recently enlisted recruits from across the alliance", "Multinational medical evacuation procedures under harsh conditions"], answer: 0, ex: "'The exercise will focus on cold-weather operations and interoperability between national forces' — direct statement of focus areas." },
    { topic: "Communication protocols", passage: "All units must follow standard NATO radio procedures when transmitting operational information. Messages should be brief and clearly structured. Sensitive information must not be transmitted in clear text and must be encoded prior to transmission. If communication is lost, units should attempt contact every five minutes using the alternate frequency specified in the communication plan.", question: "What should units do with sensitive information before transmitting?", options: ["Send it via courier", "Encode it prior to transmission", "Transmit it quickly on the main frequency", "Wait for authorisation from headquarters"], answer: 1, ex: "'Sensitive information must not be transmitted in clear text and must be encoded prior to transmission' — Level 2 procedure comprehension." },
    { topic: "Border patrol incident", passage: "During a routine border patrol, a UN observer team detected unauthorised movement across the demarcation line. The team reported the incident through standard reporting channels and continued observation from a safe distance. Local authorities were notified within ten minutes. The observers did not engage and waited for further instructions from the mission commander.", question: "What did the observer team do after detecting the unauthorised movement?", options: ["They engaged the suspected violators with non-lethal force in line with rules of engagement", "They withdrew immediately to the nearest forward position and stood down", "They reported and continued observation from a safe distance", "They requested air support from the regional command centre via secure radio"], answer: 2, ex: "'The team reported the incident... and continued observation from a safe distance' — observers in UN missions follow strict report-not-engage rules." },
    { topic: "Equipment failure report", passage: "Following the recent exercise, three units reported failures of their thermal imaging equipment. Initial investigation suggests the failures occurred due to extreme cold conditions during night operations. The manufacturer has been contacted and is sending technical specialists. Until the issue is resolved, affected units will use alternative night vision equipment from the unit reserve.", question: "What will affected units use until the equipment is repaired?", options: ["No night vision equipment for the foreseeable future, pending vendor response", "Equipment temporarily borrowed from neighbouring allied forces in theatre", "Day-only operations until full repairs are complete and certified", "Alternative night vision equipment from reserve stocks"], answer: 3, ex: "'Affected units will use alternative night vision equipment from the unit reserve' — interim solution comprehension." },
    { topic: "Civil affairs project", passage: "The civil affairs team has launched a project to repair the damaged school in the local community. The project includes replacing the roof, fixing broken windows, and providing new desks and chairs. Local workers have been hired to assist with the construction. The project is expected to be completed within three weeks. Funding is provided through NATO civil cooperation funds.", question: "Who is performing the construction work?", options: ["Local workers hired to assist", "NATO military engineers only", "Local civilian contractors only", "Volunteers from neighbouring villages"], answer: 0, ex: "'Local workers have been hired to assist with the construction' — civil-military cooperation often involves hiring local labour to support both reconstruction and the local economy." },
    { topic: "Intelligence summary", passage: "The intelligence summary for the week reports increased activity in the eastern sector. A small armed group has been observed conducting reconnaissance along Route Yellow on three separate occasions. The group has not engaged with patrols. However, their pattern of activity suggests preparation for future operations. All patrols in the area are advised to maintain heightened vigilance.", question: "What is suggested by the armed group's pattern of activity?", options: ["They are withdrawing from the area", "They are preparing for future operations", "They are engaging in humanitarian work", "They have established a permanent base"], answer: 1, ex: "'Their pattern of activity suggests preparation for future operations' — interpretation of intelligence indicators is core to Level 2 reading." },
    { topic: "Field hospital operations", passage: "The field hospital handles all medical emergencies in the operational area. The facility has 50 beds and three operating theatres. Medical staff includes general surgeons, anaesthetists, and trauma specialists. Helicopter medevac is available 24 hours a day. Patients requiring specialised treatment are transferred to the regional hospital after stabilisation.", question: "What happens to patients who need specialised treatment?", options: ["They remain at the field hospital indefinitely under continued observation", "They are sent home to recover with civilian medical follow-up from their family physician", "They are transferred to the regional hospital after stabilisation", "They are flown to their home countries for specialist treatment within seventy-two hours"], answer: 2, ex: "'Patients requiring specialised treatment are transferred to the regional hospital after stabilisation' — 'after stabilisation' is a key sequencing detail." },
    { topic: "Supply chain disruption", passage: "Recent severe weather has disrupted the supply chain to forward bases. Three convoys have been delayed by an average of 36 hours. Helicopter resupply has been limited due to poor visibility. Stocks of fuel and rations remain adequate for seven days at current consumption rates. The situation is being closely monitored and contingency plans are being prepared.", question: "How long will current stocks last at current consumption rates?", options: ["Three days", "Five days", "Two weeks", "Seven days"], answer: 3, ex: "'Stocks of fuel and rations remain adequate for seven days at current consumption rates' — note 'at current consumption rates' as a key conditional." },
    { topic: "Joint patrol procedure", passage: "Joint patrols with local security forces are conducted twice weekly. Each patrol includes four NATO soldiers and four local officers. The patrol commander is rotated between the two forces. Patrols cover a fixed route and last approximately three hours. The aim is to build trust with the local population and improve security cooperation.", question: "How is the patrol commander selected?", options: ["Command rotates between the two forces", "The senior NATO officer always commands", "The local officer always commands", "Command is shared at all times"], answer: 0, ex: "'The patrol commander is rotated between the two forces' — note that rotation differs from sharing or fixed assignment." },
    { topic: "Casualty evacuation drill", passage: "All combat units conducted a casualty evacuation drill last week. The exercise tested the speed and effectiveness of medical response. Average evacuation time from point of injury to medical facility was 45 minutes. The target is 30 minutes. Areas for improvement include radio communication delays and helicopter response times. Additional training is scheduled for next month.", question: "What is the target evacuation time?", options: ["15 minutes", "30 minutes", "45 minutes", "60 minutes"], answer: 1, ex: "'The target is 30 minutes' — note the contrast: actual time was 45 minutes, target is 30 minutes. Level 2 often tests this kind of contrast." },
    { topic: "Operational briefing format", passage: "All operational briefings follow a standard format. The first section covers the situation, including weather, terrain, and enemy activity. The second section presents the mission objective. The third section details execution, including timings, routes, and assigned tasks. The final section covers logistics and command relationships. Questions are taken at the end.", question: "What is presented in the second section of the briefing?", options: ["Weather and terrain", "Logistics arrangements", "The mission objective", "Command relationships"], answer: 2, ex: "'The second section presents the mission objective' — sequence comprehension. The standard NATO briefing format follows: Situation, Mission, Execution, Logistics/Command." },
    { topic: "Live-fire safety briefing", passage: "Before any live-fire exercise, all participants attend a mandatory safety briefing. The briefing covers weapon handling, range procedures, and emergency stop signals. Anyone who misses the briefing cannot participate in the exercise. Range officers conduct safety checks before, during, and after firing. All personnel must wear ear and eye protection at all times on the range.", question: "What is the consequence of missing the safety briefing?", options: ["A formal warning recorded in their file", "Mandatory attendance at a later session", "A fine deducted from monthly pay", "Cannot participate in the exercise"], answer: 3, ex: "'Anyone who misses the briefing cannot participate in the exercise' — direct consequence statement. Level 2 tests understanding of rules and consequences." },
    { topic: "Rules of engagement — positive identification", passage: "All personnel conducting security operations must adhere strictly to the rules of engagement. Force may only be used when a hostile act or hostile intent has been clearly identified. Positive identification of the target is mandatory before engaging. If there is any doubt about whether a person or vehicle poses a genuine threat, personnel must seek guidance from their immediate superior before taking action. Failure to follow these procedures may result in disciplinary measures and could compromise the mission's legal standing.", question: "Under what circumstances are personnel permitted to use force?", options: ["Only after a threatening action or intention has been unambiguously confirmed.", "Whenever they perceive a potential security risk in their area of operations.", "At any time, provided they inform their superior officer afterward.", "When ordered to do so by the mission commander during pre-deployment briefing."], answer: 0, ex: "'Force may only be used when a hostile act or hostile intent has been clearly identified' — option A paraphrases 'clearly identified' as 'unambiguously confirmed' and 'hostile act or hostile intent' as 'threatening action or intention'. B is too broad (any doubt requires seeking guidance). C reverses the sequence. D is fabricated. Distractor B uses 'security' from the passage to tempt surface readers." },
    { topic: "Rules of engagement — escalation of force", passage: "The escalation of force procedure requires personnel to use the minimum level of force necessary to achieve mission objectives. Personnel must issue verbal warnings and hand signals before resorting to warning shots. Warning shots must be aimed safely away from individuals. Only if these measures fail to stop a threat may personnel engage with direct fire. All use of force must be reported immediately through the chain of command, regardless of whether injuries occurred.", question: "What must happen before personnel may fire directly at a target?", options: ["The chain of command must grant explicit authorization for the engagement.", "Non-lethal deterrent measures must have proven insufficient to halt the threat.", "Personnel must confirm that injuries are likely to occur if they do not act.", "The target must be within effective range for small arms fire."], answer: 1, ex: "'Only if these measures fail to stop a threat may personnel engage with direct fire' — option B paraphrases 'these measures fail' as 'non-lethal deterrent measures proven insufficient'. The passage describes warnings/signals/warning shots as preceding direct fire. A is not in the text (reporting is required, but authorization before direct fire is not mentioned). C and D are plausible additions but not stated. Surface matching fails: 'warning shots', 'verbal warnings' are not in any option." },
    { topic: "Legal obligations — treatment of detainees", passage: "Personnel who detain individuals during operations must treat them in accordance with international humanitarian law. Detainees must be protected from physical harm, provided with food and water, and given access to medical care if required. They must not be subjected to interrogation by personnel not specifically trained and authorized to conduct such activities. All detentions must be documented with the detainee's name, time and location of detention, and reason for detention. This information must be forwarded to the legal officer within six hours.", question: "What restriction does the passage place on questioning detained persons?", options: ["Questioning must occur within six hours of the initial detention, regardless of the detainee's condition.", "Detainees must first receive a full medical assessment and care before any substantive questions are asked.", "Only individuals with appropriate training and authorization may conduct interrogations.", "All questioning must be supervised in person by the unit's designated legal officer at all times."], answer: 2, ex: "'They must not be subjected to interrogation by personnel not specifically trained and authorized' — option C paraphrases 'trained and authorized' as 'appropriate training and authorization'. A misreads the six-hour deadline (it's for documentation, not interrogation). B and D are plausible fabrications. Distractor A uses '6 hours' from the text; D uses 'legal officer' — both punish surface matching." },
    { topic: "Patrol procedures — vehicle checkpoint", passage: "Vehicle checkpoints are established to control access to secure areas and to detect unauthorised movement. All approaching vehicles must be signalled to stop at least fifty meters before the checkpoint. Personnel conduct visual inspection of the vehicle and verify the identity of occupants against authorised personnel lists. Vehicles carrying prohibited items or whose occupants lack proper documentation are directed to a holding area pending further investigation. The checkpoint commander maintains a log recording all vehicles processed and any incidents that occur.", question: "What determines whether a vehicle is allowed to proceed through the checkpoint?", options: ["Whether it stops within fifty meters of the checkpoint position.", "Whether the checkpoint commander has recorded the vehicle in the log.", "Whether the vehicle matches the description provided in the daily intelligence brief.", "Whether the occupants appear on approved lists and the vehicle contains no forbidden materials."], answer: 3, ex: "Vehicles are held if they carry 'prohibited items' or occupants 'lack proper documentation' — the converse (passing) requires proper documentation (i.e., being on authorized lists) and no prohibited items. Option D captures both conditions. A misreads (50m is the stopping distance, not the decision criterion). C confuses correlation (logging happens for all vehicles) with causation. C is fabricated. Distractors use 'fifty meters', 'log', 'commander' from the passage to punish keyword matching." },
    { topic: "Patrol operations — route reconnaissance", passage: "Before conducting a convoy movement, reconnaissance teams survey the planned route to identify potential hazards. The team records the condition of road surfaces, the location of bridges and narrow sections, and any signs of recent digging or disturbance that might indicate improvised explosive devices. Observable civilian activity along the route is also noted. The reconnaissance report is submitted to the operations officer at least four hours before the convoy departs, allowing time for route adjustments if necessary.", question: "Why is the reconnaissance report required four hours in advance?", options: ["To give the operations officer sufficient time to modify the convoy's path if needed.", "To allow reconnaissance teams to conduct a second survey of the route.", "To ensure that civilian activity can be monitored continuously until the convoy departs.", "To comply with the standard reporting timeline established in operational orders."], answer: 0, ex: "'Allowing time for route adjustments if necessary' — option A paraphrases 'route adjustments' as 'modify the convoy's path'. B is plausible but unmentioned. C misreads (civilian activity is observed during recon, not continuously monitored). D uses 'operational orders' to sound official but is fabricated. The key inference: advance notice enables adaptation." },
    { topic: "Security incident — immediate actions", passage: "In the event of a security incident such as an attack on a patrol, personnel must immediately take cover and return fire if engaged. The patrol leader reports the incident to headquarters using the standard contact report format, providing grid location, number of attackers, weapons observed, and casualty status. Headquarters dispatches a quick reaction force if the situation requires reinforcement. Once the immediate threat has been neutralized, the patrol secures the site for investigation and prepares a detailed written incident report.", question: "When does the patrol leader transmit information to headquarters?", options: ["After the site has been secured and a detailed written report has been completed.", "As soon as the patrol has taken cover following the initial engagement.", "Only if headquarters specifically requests a situation update.", "Once reinforcements have arrived and assumed control of the site."], answer: 1, ex: "The patrol leader 'reports the incident to headquarters' immediately after 'personnel must immediately take cover and return fire' — the reporting happens in the initial phase. Option B captures 'as soon as... following the initial engagement'. A reverses the sequence (written report comes later). C and D contradict the immediate reporting requirement. The distractor A is tempting because 'detailed written report' appears later in the passage." },
    { topic: "Supply request procedures", passage: "Units requiring additional supplies must submit requests through the logistics system at least seventy-two hours before the material is needed. Requests must specify the item nomenclature, quantity, and justification for the requirement. Emergency requests for critical items can be expedited through the duty officer, but these require approval from the battalion commander. Routine requests are processed in order of submission, while priority is given to operational units engaged in active missions.", question: "What distinguishes emergency supply requests from routine ones?", options: ["Emergency requests must be submitted more than seventy-two hours in advance.", "Emergency requests are limited to items that are classified as critical by the logistics officer.", "Emergency requests require higher-level approval and can bypass standard processing time.", "Emergency requests can only be made by operational units engaged in active missions."], answer: 2, ex: "Emergency requests 'can be expedited through the duty officer, but these require approval from the battalion commander' — option C paraphrases 'expedited' as 'bypass standard processing time' and names the higher approval (battalion commander). A reverses the timing (emergency requests are for urgent needs, not advance planning). B misreads (critical items can be expedited, but the passage doesn't say only the logistics officer classifies them). D misreads priority (operational units get priority for routine requests, but emergency requests are a separate category open to any unit with justification)." },
    { topic: "Equipment maintenance — reporting failures", passage: "All equipment failures must be reported immediately to the unit maintenance officer. Personnel complete a fault report form describing the nature of the malfunction, when it was discovered, and any relevant operational circumstances. Critical equipment failures that affect mission capability are classified as priority repairs. Non-critical failures are addressed during scheduled maintenance periods. Equipment that cannot be repaired at unit level is evacuated to the base workshop for specialist attention.", question: "How is repair urgency determined for malfunctioning equipment?", options: ["By whether the failure occurred during an operational task or a training activity.", "By the elapsed time since the equipment was last inspected by maintenance personnel.", "By consulting the manufacturer's technical manual for guidance on fault severity.", "By assessing whether the malfunction compromises the unit's ability to perform its mission."], answer: 3, ex: "'Critical equipment failures that affect mission capability are classified as priority repairs' — option D paraphrases 'affect mission capability' as 'compromises the unit's ability to perform its mission'. A, B, C are plausible factors but not mentioned in the passage as the determining criterion. Distractor A uses 'operational' from the passage to tempt surface readers." },
    { topic: "Casualty evacuation priority", passage: "Medical evacuation priorities are assigned based on the severity of injuries and the likelihood of survival with timely treatment. Priority One casualties have life-threatening injuries requiring immediate evacuation. Priority Two casualties have serious injuries that require evacuation within four hours. Priority Three casualties have minor injuries that can be treated at the unit level or evacuated when transport is available. The senior medical officer at the scene determines the priority category for each casualty.", question: "What principle guides the classification of casualties into priority categories?", options: ["The degree to which injuries threaten life and the urgency of obtaining medical intervention.", "The total number of casualties that can be accommodated on available evacuation aircraft.", "The rank and position of the injured individual within the unit's chain of command.", "The distance from the casualty's location to the nearest medical treatment facility."], answer: 0, ex: "'Based on the severity of injuries and the likelihood of survival with timely treatment' — option A paraphrases this as 'degree to which injuries threaten life' (severity) and 'urgency of obtaining medical intervention' (timely treatment). A focuses on transport logistics, not medical need. C is ethically implausible and unmentioned. D is a practical factor but not stated as the classification principle. Level 2 inference: recognizing the organizing principle behind a categorization scheme." },
    { topic: "First aid procedures — trauma management", passage: "When providing first aid to trauma casualties, personnel must first ensure the scene is safe before approaching the injured person. The initial assessment follows the ABC protocol: Airway, Breathing, Circulation. If the casualty is not breathing, personnel begin rescue breathing immediately. Severe bleeding must be controlled using direct pressure or tourniquets if pressure alone is insufficient. All first aid actions taken are documented on the casualty's field medical card, which accompanies the casualty during evacuation.", question: "What must occur before personnel begin treating an injured person?", options: ["The casualty's field medical card must be prepared and attached to the patient.", "Personnel must verify that approaching the casualty does not place them at risk.", "The ABC assessment protocol must be reviewed to ensure proper sequencing.", "Communication must be established with medical evacuation coordination."], answer: 1, ex: "'Personnel must first ensure the scene is safe before approaching the injured person' — option B paraphrases 'ensure the scene is safe' as 'verify that approaching does not place them at risk'. A reverses sequence (card is completed after treatment). C misreads (ABC is the assessment method, not something reviewed beforehand). D is not required before initial first aid. The key word is 'first' in the passage — it establishes temporal priority." },
    { topic: "Intelligence reporting — information requirements", passage: "Intelligence reports submitted to headquarters must address the priority information requirements established by the commander. These requirements typically include enemy activity, terrain conditions, and civilian population movements. Reports must distinguish between information directly observed by the reporting unit and information obtained from secondary sources such as local informants. All reports include the time and location of the observation and an assessment of the information's reliability. Unconfirmed information should be clearly marked as such.", question: "Why must intelligence reports differentiate between observed and second-hand information?", options: ["Because the commander only accepts reports based on direct observation by military personnel.", "Because information from local sources is generally considered unreliable by headquarters.", "To enable analysts to evaluate the credibility of the information according to its source.", "To ensure that reports address all of the priority information requirements."], answer: 2, ex: "The passage states reports must 'include... an assessment of the information's reliability' and 'distinguish between information directly observed' vs. 'obtained from secondary sources' — the purpose is enabling reliability assessment. Option C captures this as 'evaluate the credibility according to its source'. A and B overstate (the passage doesn't reject secondary sources, it requires labeling them). D confuses two separate requirements. Level 2 inference: understanding the purpose behind a procedure." },
    { topic: "Reconnaissance mission — reporting procedures", passage: "Reconnaissance teams tasked with surveying an area must submit an initial report upon reaching the observation position. This report confirms arrival and provides a preliminary assessment of visibility and terrain. During the observation period, teams report significant activities immediately using the radio. At the conclusion of the mission, a comprehensive written report is prepared covering all observations, including negative findings such as the absence of expected enemy activity. The written report is submitted within two hours of returning to base.", question: "What is the purpose of reporting negative findings in the final report?", options: ["To demonstrate that the reconnaissance team conducted a thorough observation.", "To justify the decision to return to base at the conclusion of the observation period.", "To fulfill the requirement for a comprehensive written report within two hours.", "To inform commanders that anticipated threats did not materialize during the mission."], answer: 3, ex: "Negative findings include 'the absence of expected enemy activity' — this informs decision-makers that something anticipated didn't occur. Option D captures this as 'anticipated threats did not materialize'. A is plausible but not the stated purpose. B is fabricated (the timing is determined by mission plan, not by negative findings). D confuses a content requirement with a timing requirement. The key inference: negative intelligence (what didn't happen) is still valuable intelligence." },
    { topic: "Civil-military liaison — local coordination", passage: "The civil-military cooperation team maintains regular contact with local government officials and community leaders. These meetings serve to identify civilian needs that military assets can help address, such as repairing infrastructure or providing medical support. The team also gathers information about local concerns regarding military operations. All assistance provided must be coordinated with humanitarian organizations operating in the area to avoid duplication of effort. The team's weekly report summarizes meetings held, assistance delivered, and issues raised by the civilian population.", question: "Why is coordination with humanitarian organizations necessary?", options: ["To ensure that military assistance complements rather than replicates ongoing relief efforts.", "To obtain authorization from humanitarian agencies before providing any civilian aid.", "To share information about local security threats identified during liaison meetings.", "To fulfill the requirement for weekly reporting on civil-military activities."], answer: 0, ex: "'Coordinated with humanitarian organizations... to avoid duplication of effort' — option A paraphrases 'avoid duplication' as 'complements rather than replicates'. B overstates (the text says coordinate, not obtain authorization). C is plausible but not mentioned. D confuses two separate requirements. Level 2 question type: identifying the purpose behind a coordination requirement." },
    { topic: "Community engagement — damage compensation", passage: "When military operations result in damage to civilian property, the affected individuals may submit compensation claims to the civil affairs office. Claims must be filed within thirty days of the incident and must include evidence such as photographs or witness statements. The claims officer investigates each case to verify the damage and determine whether it resulted from military activity. Approved claims are paid from the operational budget. Claims resulting from combat operations are generally not eligible for compensation under the current policy.", question: "What determines whether a compensation claim will be approved?", options: ["Whether the claim was submitted within the thirty-day deadline.", "Whether investigation confirms the damage occurred and was caused by military actions.", "Whether photographic evidence or witness statements were provided with the claim.", "Whether the incident occurred during peacetime operations rather than combat."], answer: 1, ex: "The claims officer 'investigates each case to verify the damage and determine whether it resulted from military activity' — both conditions must be met. Option B captures both: 'confirms the damage occurred' (verification) and 'caused by military actions' (attribution). A and C are procedural requirements for filing but don't determine approval. D partially captures the exclusion for combat but misses the verification step. Surface readers may choose A because '30 days' is prominent in the passage." },
    { topic: "Joint operations — force integration", passage: "The multinational task force includes units from four contributing nations. Each national contingent operates under its own command structure but coordinates activities through the joint operations center. National commanders retain authority over their forces for administrative matters and must approve any operational orders that place their troops at significant risk. The force commander issues daily tasking orders specifying missions for each unit. Liaison officers from each nation are co-located at the operations center to facilitate coordination.", question: "What aspect of force employment remains under national rather than joint control?", options: ["The assignment of daily missions to units within each national contingent.", "The coordination of operations through the central command facility.", "Decisions regarding activities that could expose troops to substantial danger.", "The placement of liaison officers to ensure effective communication."], answer: 2, ex: "'National commanders retain authority over their forces for administrative matters and must approve any operational orders that place their troops at significant risk' — option C paraphrases 'significant risk' as 'substantial danger' and 'must approve' as 'decisions regarding'. A is wrong (force commander issues daily tasking). B and D are joint functions. This tests understanding of 'national caveats' — a core L2 concept." },
    { topic: "Combined training exercise — interoperability", passage: "The annual combined exercise brings together forces from six alliance nations to practice interoperability in a simulated operational environment. Participating units conduct joint planning, share intelligence, and execute coordinated maneuvers. The exercise includes a communications test to verify that different national radio systems can exchange information effectively. After-action reviews identify areas where procedures need improvement. The lessons learned are compiled in a final report distributed to all participating nations to inform future training.", question: "What is the primary purpose of the communications test during the exercise?", options: ["To determine which contributing nation possesses the most advanced radio technology in its inventory.", "To identify those units that require additional standardised training in coalition radio operating procedures.", "To compile information for inclusion in the exercise's after-action review report distributed to all participants.", "To confirm that equipment from different countries can successfully transmit data between systems."], answer: 3, ex: "'Communications test to verify that different national radio systems can exchange information effectively' — option D paraphrases 'exchange information effectively' as 'successfully transmit data between systems'. A misreads (the test is about compatibility, not superiority). B is plausible but not stated. D confuses purpose with outcome (findings may go into the AAR, but that's not the test's purpose). The concept being tested: interoperability assessment." },
    { topic: "Radio procedures — report format", passage: "Situation reports transmitted by radio must follow the standard format to ensure clarity and completeness. The report begins with the call sign of the reporting unit, followed by current location expressed as a grid reference. The report then states the unit's current activity and any significant observations such as enemy contact or terrain obstacles. Reports conclude with an estimate of when the next scheduled report will be transmitted. Brevity is essential to minimize transmission time and reduce the risk of interception.", question: "Why are radio transmissions kept as brief as possible?", options: ["To reduce the duration during which the transmission might be detected by adversaries.", "To ensure that all required information can be transmitted within the allocated time slot.", "To conform to the standard reporting format established in communications procedures.", "To allow other units to use the radio frequency for their own situation reports."], answer: 0, ex: "'Brevity is essential to minimize transmission time and reduce the risk of interception' — option A paraphrases 'reduce the risk of interception' as 'reduce the duration during which... might be detected'. B, C, D are plausible operational reasons but not stated in the passage. Surface readers may choose B because 'standard format' is prominent." },
    { topic: "Communication security — authentication", passage: "Before acting on orders received by radio, personnel must verify the authenticity of the transmission using the current authentication codes. These codes are changed daily and distributed through secure channels. If a message cannot be authenticated, personnel must not comply with the orders and must report the incident to their immediate superior. Failure to authenticate could allow an adversary to issue false orders. Authentication procedures apply to all operational communications, not just those containing classified information.", question: "Under what circumstances do authentication procedures apply?", options: ["Only when the orders received involve the movement of classified materials.", "Whenever operational communications are transmitted, regardless of classification level.", "Only when personnel suspect that the transmission may have originated from hostile sources.", "Whenever the daily authentication codes have been updated through secure channels."], answer: 1, ex: "'Authentication procedures apply to all operational communications, not just those containing classified information' — option B paraphrases this exactly ('regardless of classification level'). A contradicts 'not just classified'. C is wrong (authentication is required always, not just when suspicion exists). D confuses the update schedule with the applicability scope. The final sentence is the key claim being tested." },
    { topic: "Training exercise — safety supervision", passage: "Live-fire training exercises require the presence of qualified safety officers throughout the activity. Safety officers monitor the firing line to ensure personnel follow weapon handling procedures and that all rounds impact within designated safe areas. If a safety violation is observed, the safety officer has authority to halt the exercise immediately. Before the exercise begins, all participants attend a safety briefing covering range procedures, emergency signals, and the location of medical support. No one may participate in live fire without attending the briefing.", question: "What authority do safety officers possess during live-fire training?", options: ["They may conduct the safety briefing in place of the exercise commander.", "They may modify the location of designated safe impact areas during the exercise.", "They may immediately stop the exercise if unsafe practices are observed.", "They may determine which personnel are qualified to participate in live fire."], answer: 2, ex: "'Safety officer has authority to halt the exercise immediately' if violations occur — option C captures this. A is unmentioned (safety officers monitor, but we don't know who conducts briefings). B is implausible and unmentioned (impact areas are pre-designated). D is wrong (qualification isn't mentioned; attendance at the briefing is the stated requirement). Surface readers may confuse the safety officer's monitoring role with other authorities." },
    { topic: "Training exercise — performance evaluation", passage: "At the conclusion of each training exercise, unit leaders conduct an after-action review with all participants. The review examines what was planned, what actually occurred, and why any differences arose. Participants are encouraged to identify both successful actions and mistakes made during the exercise. The purpose is to facilitate learning rather than to assign blame. Key lessons are documented and incorporated into training plans for future exercises. Units that consistently demonstrate proficiency in specific tasks may be assigned more complex training scenarios.", question: "What is the intended outcome of the after-action review?", options: ["To determine which individuals are responsible for mistakes made during the exercise.", "To identify units that require remedial training before the next exercise.", "To assign more challenging tasks to participants who performed exceptionally well.", "To enhance learning by analyzing both achievements and errors that occurred."], answer: 3, ex: "'The purpose is to facilitate learning rather than to assign blame' — option D paraphrases 'facilitate learning' and 'both successful actions and mistakes'. A directly contradicts 'rather than to assign blame'. B is plausible but overstates (documentation is mentioned for future training, not specifically for remediation). D confuses unit-level progression with individual-level feedback. Level 2 inference: distinguishing stated purpose from potential side effects." },
    { topic: "Rules of Engagement", passage: "Under the current rules of engagement, soldiers may use lethal force only when their lives or the lives of civilians are in immediate danger. Warning shots are permitted but must be fired into the ground at a safe angle. Before engaging any target, soldiers must positively identify the threat and ensure no civilians are in the line of fire. Commanders may authorize deviation from these rules only in exceptional circumstances and must report such authorization within 24 hours to the higher command. Any violation of these rules will result in disciplinary action and possible criminal proceedings under military law.", question: "According to the passage, when can commanders allow exceptions to the ROE?", options: ["Only in unusual situations, with mandatory reporting afterwards", "Whenever they believe it is tactically necessary", "Only with prior approval from international observers", "Never, regardless of the circumstances"], answer: 0, ex: "本文の 'in exceptional circumstances and must report such authorization within 24 hours' をパラフレーズした選択肢が正解。選択肢 A は権限を過大評価し、C は本文にない情報、D は本文と矛盾する。L2 は条件と制限の理解を問う。" },
    { topic: "Humanitarian Aid Distribution", passage: "The distribution of humanitarian aid in conflict zones must follow strict neutrality principles. Aid workers are required to distribute supplies based on need rather than political affiliation, ethnicity, or religion. Local leaders may assist in identifying beneficiaries, but final distribution decisions remain with the international organization. Recipients must be registered, and each family receives a ration card. Attempts by armed groups to control distribution must be reported immediately to the mission commander. Aid convoys travel with clearly visible markings and operate only during daylight hours unless security conditions require otherwise.", question: "Why must local leaders not make final distribution decisions?", options: ["They lack the training to handle logistics", "To preserve impartiality of the aid effort", "They cannot read the ration cards", "Because international law explicitly forbids it"], answer: 1, ex: "本文の 'strict neutrality principles' と 'final distribution decisions remain with the international organization' から、中立性確保のためと理解できる。impartiality は neutrality のパラフレーズ。他の選択肢は本文に根拠がない。" },
    { topic: "Logistics Resupply", passage: "Forward operating bases receive resupply every 72 hours under normal conditions. Each resupply convoy carries food, ammunition, fuel, and medical supplies in standardized quantities calculated for a 100-person base. If casualties or increased operational tempo occur, the base commander may request an emergency resupply, which can be delivered within 12 hours by helicopter. However, helicopter delivery is restricted during periods of poor visibility or high winds, in which case ground convoys must be used despite the longer transit time. All requests must include detailed justification and current stock levels.", question: "What is implied about ground convoys compared to helicopter delivery?", options: ["They carry larger quantities of supplies", "They are safer in all weather conditions", "They take more time to reach the destination", "They require fewer personnel to operate"], answer: 2, ex: "本文の 'helicopter delivery... within 12 hours' と 'ground convoys must be used despite the longer transit time' の対比から、地上輸送の方が時間がかかると推論できる。他の選択肢は本文に言及がない。" },
    { topic: "Peacekeeping Situation Report", passage: "Sector East reports a tense but stable situation. Patrols observed increased movement of armed elements near the southern boundary, although no direct confrontations occurred. Local civilian leaders requested additional patrols after reports of nighttime intimidation. The medical team treated 15 civilians for minor injuries from a market explosion of unclear origin. Liaison with the local police has been re-established after a two-week suspension following allegations of corruption. The sector commander recommends maintaining current force levels while increasing intelligence collection in the southern area before considering any troop adjustments.", question: "What does the sector commander suggest as the next step?", options: ["Immediately reinforce the troop presence in the southern zone with reserve elements", "Withdraw alliance forces from the area entirely until the situation becomes clearer over coming days", "Transfer full operational responsibility for the area to the local civilian police authorities", "Keep forces at present strength while gathering more information"], answer: 3, ex: "本文の 'maintaining current force levels while increasing intelligence collection' を 'Keep forces at present strength while gathering more information' とパラフレーズ。A は本文と矛盾、B/D は本文に言及なし。" },
    { topic: "Counter-IED Operations", passage: "Improvised explosive devices remain the leading cause of casualties in current operations. Convoys must vary their routes and timing to prevent enemy planning. Lead vehicles are equipped with electronic countermeasures that disrupt remote detonation signals, but these devices are ineffective against pressure-plate triggers. Engineer teams precede high-value convoys to identify and clear suspicious areas. When an IED is suspected, the convoy halts at a safe distance while specialists assess the threat. Detonation is preferred to manual disposal whenever the surrounding area permits. Civilian movement in the vicinity must be controlled but not prevented entirely.", question: "What is a limitation of the electronic countermeasures mentioned?", options: ["They cannot detect pressure-activated devices", "They consume excessive power", "They interfere with friendly radio communications", "They only work at night"], answer: 0, ex: "本文の 'these devices are ineffective against pressure-plate triggers' を 'cannot detect pressure-activated devices' とパラフレーズ。L2 では装備の限界という条件の理解を問う。他の選択肢は本文に言及がない。" },
    { topic: "Border Patrol Coordination", passage: "Joint border patrols between allied forces have proven effective in reducing illegal crossings. Each patrol consists of soldiers from both nations who share information in real time using a common radio frequency. Language barriers are addressed by requiring at least one bilingual member per patrol. Detained individuals are processed by personnel from the country whose territory they entered, regardless of which patrol made the apprehension. Disputes regarding jurisdiction are resolved by the joint command center, which operates continuously. Equipment standardization remains incomplete, occasionally causing compatibility issues during nighttime operations.", question: "Who handles the processing of detained persons?", options: ["The nation that operates the joint command center", "Personnel from the country whose territory was entered", "The patrol member who first spotted the individual", "A neutral third-party observer organization"], answer: 1, ex: "本文の 'Detained individuals are processed by personnel from the country whose territory they entered' を直接的だがパラフレーズして問う。L2 では責任関係と条件の対応を問う。" },
    { topic: "Cyber Incident Response", passage: "When a suspicious network event is detected, the duty operator must first determine whether it represents a genuine threat or a false alarm. Automated systems flag many routine activities as anomalies, and only about ten percent require human intervention. Confirmed incidents are categorized by severity from Level 1 (minor) to Level 4 (critical infrastructure threat). Level 3 and 4 incidents require immediate notification of the national cyber command, while lower levels are handled locally with a summary report sent at the end of the shift. Disconnecting affected systems is a last resort, used only when containment cannot be achieved otherwise.", question: "When must the national cyber command be informed without delay?", options: ["After every detected network anomaly regardless of severity", "Only when systems must be disconnected from the wider network", "When incidents reach the two highest severity categories", "At the end of each duty shift in the daily summary report"], answer: 2, ex: "本文の 'Level 3 and 4 incidents require immediate notification' を 'two highest severity categories' とパラフレーズ。A は対象範囲が広すぎ、D は L1/L2 についての記述。" },
    { topic: "Civil-Military Cooperation", passage: "Civil-military cooperation officers serve as the interface between military forces and the civilian population in operational areas. Their role is not to deliver aid directly but to coordinate with humanitarian organizations and local authorities. By understanding local needs, they help commanders avoid actions that might alienate the population. CIMIC officers attend community meetings, although they wear uniforms and remain identifiable as military personnel. They are unarmed during civilian engagements whenever the security situation allows, projecting an image of partnership rather than force. Reports from CIMIC officers inform both operational planning and reconstruction efforts.", question: "What is the primary function of CIMIC officers?", options: ["Distributing food and medical supplies to local people", "Replacing civilian government officials in conflict zones", "Conducting intelligence operations against insurgents", "Serving as a link between troops and the civilian community"], answer: 3, ex: "本文の 'interface between military forces and the civilian population' を 'link between troops and the civilian community' とパラフレーズ。A は本文で明確に否定されている ('not to deliver aid directly')。" },
    { topic: "Maritime Interdiction", passage: "Maritime interdiction operations aim to enforce embargoes and prevent the movement of prohibited goods. When a suspect vessel is identified, the boarding team approaches in a smaller craft and requests permission to come aboard. If permission is denied or the vessel attempts to flee, the team may use non-lethal means to compel cooperation. Lethal force is reserved for cases of armed resistance. Once aboard, the team inspects cargo against the manifest and may detain crew members if violations are confirmed. The detained vessel is escorted to the nearest friendly port, where civilian authorities take over proceedings.", question: "What happens after a vessel is detained?", options: ["It is taken to a nearby allied port for civilian processing", "It is sunk to prevent the cargo from reaching its destination", "The crew is transferred to a military prison facility", "It is released after the cargo is confiscated at sea"], answer: 0, ex: "本文の 'escorted to the nearest friendly port, where civilian authorities take over' を 'taken to a nearby allied port for civilian processing' とパラフレーズ。L2 では手続きの流れを問う。" },
    { topic: "Air Support Coordination", passage: "Close air support requires precise coordination between ground forces and aircraft to avoid friendly fire. A forward air controller on the ground identifies the target and communicates its position to the pilot using standardized procedures. Both must confirm the target description before any weapon release. If the ground commander loses radio contact with the controller, the mission is aborted regardless of how close the aircraft is to engagement. Visual identification by the pilot is required in addition to radio confirmation when civilians are believed to be in the area. These layered safeguards significantly reduce, though they do not eliminate, the risk of mistaken targeting.", question: "What is implied about the safety procedures described?", options: ["They make accidental targeting impossible", "They reduce but cannot completely prevent errors", "They are required only during night operations", "They apply only when civilians are confirmed present"], answer: 1, ex: "本文の 'significantly reduce, though they do not eliminate, the risk' を 'reduce but cannot completely prevent errors' とパラフレーズ。A は本文と矛盾、B/D は対象範囲を不当に狭めている。" },
    { topic: "Medical Evacuation", passage: "Medical evacuation procedures are categorized by urgency level. Priority One patients require evacuation within one hour and include those with life-threatening injuries. Priority Two patients must be evacuated within four hours and have serious but not immediately life-threatening conditions. Priority Three patients can wait up to 24 hours and have minor injuries. Helicopters are used for Priority One and Two cases when weather permits, while ground ambulances handle Priority Three or serve as backup when air assets are unavailable. The medical officer at the collection point determines the priority level based on triage assessment.", question: "What determines which patients are evacuated by helicopter?", options: ["The patient's military rank", "The distance to the nearest hospital", "The urgency level and weather conditions", "The availability of ground ambulances"], answer: 2, ex: "本文の 'Helicopters are used for Priority One and Two cases when weather permits' から、緊急度と天候の両方が条件。他の選択肢は本文に根拠なし。" },
    { topic: "Military Justice", passage: "Disciplinary proceedings in the military follow a different procedure than civilian courts. Minor infractions are handled at the unit level through non-judicial punishment, which may include extra duties, restriction to base, or reduction in rank. More serious offenses are referred to courts-martial, which come in three types: summary, special, and general. A summary court-martial handles the least serious cases and can impose limited punishments. Special and general courts-martial deal with more severe offenses and operate with full legal representation and formal procedures. The accused has the right to decline a summary court-martial and demand trial by special or general court-martial instead.", question: "What option does an accused person have regarding a summary court-martial?", options: ["They must accept it if ordered by their commander", "They can appeal directly to civilian courts", "They must wait for automatic promotion to special court-martial", "They can refuse it and request a more formal trial"], answer: 3, ex: "本文の 'The accused has the right to decline a summary court-martial and demand trial by special or general court-martial' を選択肢 B がパラフレーズ。L2 は権利と手続きの関係を問う。" },
    { topic: "Intelligence Gathering", passage: "Human intelligence collection requires building relationships with sources over time. Intelligence officers must establish trust while maintaining operational security. Sources are categorized by reliability and access, with ratings assigned based on past reporting accuracy and their position to obtain information. Single-source intelligence is rarely acted upon without corroboration from technical or other human sources. The identity of sources must be protected even within intelligence organizations through compartmentalization. When intelligence is shared with operational units, it is sanitized to remove identifying details that could compromise sources if captured or leaked.", question: "Why is intelligence information modified before sharing with operational units?", options: ["To protect the identity of information sources", "To make it easier for soldiers to understand", "To reduce the file size for transmission", "To comply with international humanitarian law"], answer: 0, ex: "本文の 'it is sanitized to remove identifying details that could compromise sources' を 'protect the identity of information sources' とパラフレーズ。他の選択肢は本文に根拠なし。" },
    { topic: "Operational Security", passage: "Operational security measures are designed to prevent adversaries from piecing together information about planned operations. Even innocuous details like increased fuel deliveries, changes in communication patterns, or the movement of specialized units can reveal intentions to a careful observer. Personnel are instructed to avoid discussing operations outside secure areas and to limit knowledge of plans to those with a genuine need to know. Social media use is particularly problematic, as location data, timestamps, and casual comments can be aggregated to form an intelligence picture. Security breaches are often unintentional, resulting from a failure to recognize the cumulative value of small pieces of information rather than from deliberate disclosure of classified material.", question: "What does the passage suggest about most security breaches?", options: ["They result from sophisticated hacking operations", "They happen when individuals fail to see how small details combine", "They occur because people deliberately sell secrets", "They are primarily caused by foreign intelligence agents"], answer: 1, ex: "本文の 'Security breaches are often unintentional, resulting from a failure to recognize the cumulative value of small pieces of information' を選択肢 C がパラフレーズ。A/B/D は本文と異なる原因を示している。" },
    { topic: "Multinational Exercises", passage: "Large-scale multinational exercises serve multiple purposes beyond training individual units. They test command structures, communications systems, and logistics networks under realistic conditions. Participating nations use different equipment, follow different procedures, and often speak different languages, requiring extensive pre-exercise coordination. The exercise scenario typically involves a fictional conflict to avoid political sensitivities, though the geographic setting and operational challenges often reflect real-world concerns. Observers from non-participating nations are sometimes invited to enhance transparency and build confidence. After-action reviews identify interoperability problems that must be addressed before the next exercise cycle.", question: "Why do exercise scenarios use fictional conflicts?", options: ["To make them more interesting for participants", "To reduce costs by simplifying planning", "To prevent political complications with real nations", "To allow testing of experimental weapons systems"], answer: 2, ex: "本文の 'fictional conflict to avoid political sensitivities' を 'prevent political complications' とパラフレーズ。L2 では理由と結果の因果関係を問う。" },
    { topic: "Force Protection", passage: "Force protection measures balance security needs against operational effectiveness. Excessive defensive measures can isolate units from the local population, undermining the relationship-building that many missions require. Conversely, inadequate protection exposes personnel to unnecessary risk. Threat assessments determine the appropriate level of protection, which can range from minimal measures during low-threat operations to full fortification in high-threat environments. Measures include physical barriers, armed guards, access control, surveillance systems, and patrol patterns. Protection levels must be reviewed regularly as threat conditions change. Units that fail to adjust to deteriorating conditions may suffer preventable casualties, while those that maintain excessive security after threats diminish waste resources and limit their effectiveness.", question: "What trade-off does the passage identify regarding force protection?", options: ["Between cost and effectiveness of security equipment", "Between domestic and international protection standards", "Between officer safety and enlisted safety", "Between security requirements and mission accomplishment"], answer: 3, ex: "本文の 'balance security needs against operational effectiveness' と 'Excessive defensive measures can isolate units... undermining relationship-building' が security と mission の trade-off を示す。" },
    { topic: "Contract Management", passage: "Military operations increasingly rely on civilian contractors for services ranging from food preparation to equipment maintenance. Contracting officers must ensure that agreements include clear performance standards, accountability mechanisms, and appropriate oversight. In operational environments, contractors operate under different legal frameworks than military personnel, which can create complications when contractors are accused of misconduct. Some host nations object to the presence of armed contractors, viewing them as mercenaries, while others accept them as a practical necessity. Contract terms must address what happens if security conditions deteriorate to the point where contractors cannot safely perform their duties. Dependency on contractors has grown to the extent that some military capabilities cannot be sustained without them.", question: "What concern does the passage raise about contractor dependency?", options: ["Some military functions now cannot operate without contractor support", "Contractors invariably cost considerably more than military personnel for equivalent work", "Contractors routinely refuse to work in areas designated as dangerous by the unit", "Contractors are systematically better trained than regular soldiers across the relevant technical fields"], answer: 0, ex: "本文最終文 'Dependency on contractors has grown to the extent that some military capabilities cannot be sustained without them' を選択肢 B がパラフレーズ。他の選択肢は本文に根拠なし。" },
    { topic: "Environmental Impact", passage: "Military training and operations can have significant environmental impacts that must be managed. Live-fire exercises leave unexploded ordnance that poses long-term hazards to civilians and wildlife. Vehicle maneuvers can damage sensitive ecosystems and accelerate soil erosion. Noise from aircraft and artillery affects both human communities and animal populations. Environmental regulations in many countries now require impact assessments before training areas can be established or expanded. Some ranges have been closed or restricted due to contamination from decades of use. Remediation of former military sites is expensive and technically challenging, particularly when heavy metals or other persistent contaminants are present. Balancing training realism with environmental responsibility requires careful planning and sometimes acceptance of training limitations.", question: "What does the passage suggest about environmental regulations and military training?", options: ["They have been completely eliminated for national security reasons", "They now impose requirements that affect training site decisions", "They apply only to naval operations", "They are enforced only during peacetime"], answer: 1, ex: "本文の 'Environmental regulations... now require impact assessments before training areas can be established or expanded' を選択肢 B がパラフレーズ。" },
    { topic: "Cultural Awareness", passage: "Cultural awareness training has become a standard component of pre-deployment preparation for forces operating in unfamiliar regions. Understanding local customs, religious practices, and social structures helps prevent misunderstandings that could escalate into confrontations. Simple gestures that are innocuous in one culture may be deeply offensive in another. Language training beyond basic phrases enhances effectiveness but requires time that operational schedules do not always permit. Cultural advisors, often recruited from diaspora communities or academic institutions, accompany units to provide real-time guidance. However, cultural knowledge alone cannot overcome policy decisions that locals perceive as unjust or operations that cause civilian casualties. Even culturally informed operations may fail if the underlying mission lacks legitimacy in the eyes of the affected population.", question: "What limitation of cultural awareness training does the passage mention?", options: ["It is too expensive to provide to all deployed personnel before mission start", "It requires learning languages widely regarded as too difficult to master in time", "It cannot compensate for policies the population views as illegitimate", "It is generally opposed by senior military commanders concerned about training time"], answer: 2, ex: "本文の 'cultural knowledge alone cannot overcome policy decisions that locals perceive as unjust' と 'Even culturally informed operations may fail if the underlying mission lacks legitimacy' を選択肢 B がパラフレーズ。" },
    { topic: "Mental Health Support", passage: "Recognition of combat stress and post-traumatic stress disorder has led to expanded mental health support for military personnel. Early intervention programs aim to identify psychological problems before they become severe. Peer support networks encourage soldiers to discuss difficulties with trusted colleagues rather than suppressing them. However, stigma around mental health issues persists in many military cultures, where seeking help may be seen as weakness. Anonymous counseling services partially address this concern but cannot replace unit-level awareness. Commanders play a critical role by creating an environment where personnel feel safe reporting psychological distress. Untreated mental health conditions can lead to substance abuse, relationship breakdowns, and in extreme cases, suicide or violence.", question: "What barrier to effective mental health care does the passage identify?", options: ["Insufficient funding for counseling programs", "A lack of qualified mental health professionals", "The geographic isolation of military bases", "Cultural attitudes that discourage seeking help"], answer: 3, ex: "本文の 'stigma around mental health issues persists in many military cultures, where seeking help may be seen as weakness' を選択肢 C がパラフレーズ。L2 は障壁の識別を問う。" }
  ],
  3: [
    { topic: "Collective defence — Article 5", passage: "Article 5 of the North Atlantic Treaty constitutes the cornerstone of NATO's collective defence framework. It stipulates that an armed attack against one or more member nations shall be considered an attack against the alliance as a whole. Member states are obligated to take such action as they deem necessary, including the use of armed force, to restore and maintain the security of the North Atlantic area. The article has been invoked only once in the alliance's history, following the terrorist attacks of 11 September 2001 in the United States. The decision was unanimous among the then nineteen members. The practical response included the deployment of airborne early warning aircraft to patrol American airspace and the launch of maritime counter-terrorism operations in the Mediterranean. The episode demonstrated that the mutual defence commitment was not merely declaratory.", question: "What does the text imply about NATO's response after September 11?", options: ["It led to a permanent restructuring of the North Atlantic Treaty's collective defence provisions in their entirety.", "It revealed deep divisions among the nineteen members regarding the legitimate use of armed force in self-defence.", "It marked the first occasion on which the alliance translated its founding pledge into operational measures.", "It was limited to symbolic gestures rather than concrete military activity in the operational theatre that followed."], answer: 2, ex: "The final sentence — 'demonstrated that the mutual defence commitment was not merely declaratory' — implies that prior to this, the commitment had never been operationalised. Distractor A over-generalises (no restructuring is mentioned). B contradicts 'unanimous'. D contradicts the deployment of aircraft and maritime operations. Note: no option uses the word 'invoke' or '9/11' from the passage — surface matching fails." },
    { topic: "Air superiority doctrine", passage: "Air superiority is the degree of dominance in air battle by one force that permits the conduct of its operations at a given time and place without prohibitive interference by the opposing force. Achieving and maintaining it is a fundamental prerequisite for the success of joint military operations. Modern campaigns to establish such dominance involve a combination of the suppression of enemy air defences, counter-air operations, and electronic warfare. The Italian Air Force has accumulated significant expertise through participation in alliance missions, notably its rotational deployments to the Baltic region, where allied air forces patrol the airspace of states that lack their own combat aviation capability. This standing mission has continued uninterrupted since 2004 and is among the alliance's most visible peacetime commitments.", question: "Which statement best captures the strategic logic of the Baltic deployment described?", options: ["It serves primarily as a training opportunity for Italian pilots.", "It represents a temporary measure pending the development of Baltic national air forces.", "It is intended as a deterrent against hostile electronic warfare activities.", "It substitutes for capabilities that certain member states do not themselves possess."], answer: 3, ex: "The text states the deployment patrols airspace of states 'that lack their own combat aviation capability' — option D paraphrases this as substituting for missing capabilities. A is plausible but unmentioned. B is contradicted by 'continued uninterrupted since 2004' (permanent, not pending). D conflates two separate paragraph topics (electronic warfare was mentioned regarding campaigns, not the Baltic mission)." },
    { topic: "Cyber operations and hybrid threats", passage: "Modern hybrid warfare combines conventional military operations with cyber attacks, disinformation campaigns, and economic pressure. The alliance has formally recognised cyber space as an operational domain alongside land, sea, air, and space. A significant intrusion can trigger consultations under Article 4 of the North Atlantic Treaty, and, in severe cases, may be deemed equivalent to an armed attack, potentially invoking Article 5. The principal difficulty in such cases is establishing responsibility, a process that is often protracted and inconclusive. Without firm identification of the perpetrator, the alliance struggles to determine proportionate responses. This obstacle is compounded by the fact that adversaries deliberately employ techniques designed to maintain ambiguity regarding the true source of an operation.", question: "According to the text, what fundamentally limits the alliance's capacity to respond to cyber operations?", options: ["Difficulties in conclusively identifying who carried out an operation.", "The absence of legal frameworks treating cyber attacks as armed attacks.", "The reluctance of member states to invoke Article 4 consultations.", "Insufficient technical expertise within NATO cyber defence units."], answer: 0, ex: "'The principal difficulty... is establishing responsibility' — option A paraphrases 'establishing responsibility' as 'conclusively identifying who carried out'. The passage explicitly says Article 5 CAN be invoked, so B is wrong. C and D are not in the text — they are plausible-sounding fabrications. Surface matching would fail because the answer doesn't reuse 'attribution', 'attribute', or 'perpetrator'." },
    { topic: "Evolving peacekeeping mandates", passage: "United Nations Security Council Resolution 1674, adopted in 2006, reaffirmed the international community's responsibility to protect civilians in armed conflict. Under this framework, peacekeeping forces are not merely observers but are mandated to take active measures to prevent violations of international humanitarian law. This represents a significant departure from the traditional peacekeeping model, in which forces were expected to maintain neutrality and use force only in strict self-defence. The new approach has proved controversial. Critics argue that the expanded mandate blurs the distinction between peacekeeping and peace enforcement, potentially compromising the perceived impartiality of UN operations. Supporters counter that the moral imperative to protect civilians overrides concerns about traditional doctrine.", question: "What is the central concern raised by those who oppose the post-2006 framework?", options: ["That UN forces lack the equipment necessary for active enforcement.", "That actively intervening may undermine the appearance of being a neutral party.", "That the legal authority underlying Resolution 1674 is questionable.", "That moral imperatives should not take precedence over operational doctrine."], answer: 1, ex: "Critics argue the new mandate 'compromises the perceived impartiality' — option B paraphrases 'perceived impartiality' as 'appearance of being a neutral party'. A and C are unmentioned. D inverts the supporter/critic positions (the supporters argue moral imperative wins; the critics don't argue against this on doctrinal grounds — they argue from a perception standpoint). Note that no option uses 'impartiality', 'peace enforcement', or 'controversial' from the passage." },
    { topic: "Environmental considerations in operations", passage: "Contemporary military doctrine increasingly acknowledges the ecological consequences of operations. Fuel consumption, waste management, and the use of hazardous materials present both operational challenges and legal obligations under international environmental agreements. NATO's Environmental Protection Best Practices aim to minimise the ecological footprint of alliance activities without compromising operational effectiveness. Member nations are encouraged to adopt green technologies, including renewable energy sources at forward operating bases. Solar installations have proven particularly effective in remote locations where fuel resupply is costly and dangerous. These initiatives reduce both ecological harm and a critical operational vulnerability, since fuel convoys have historically been a frequent target of hostile attack.", question: "What is the principal reason given for installing solar power at forward bases?", options: ["Compliance with international environmental agreements requires alternative energy sources.", "Diesel generators have become prohibitively expensive in current operations.", "Reducing dependence on fuel convoys serves both ecological and security purposes.", "Solar technology has reached parity in reliability with conventional generation."], answer: 2, ex: "The closing sentence makes the dual rationale explicit: 'reduce both ecological harm and a critical operational vulnerability'. C captures this. A is wrong because compliance is not stated as the driver. B is unmentioned. D is not in the text. Surface matching fails: no option uses 'renewable', 'green', 'solar', or 'footprint'." },
    { topic: "Multinational command", passage: "Effective command in multinational operations is complicated by disparities in doctrine, interoperability limitations, national caveats, and divergent risk tolerances among contributing nations. The principle of unity of command, while theoretically optimal, is frequently subordinated to political considerations that produce compromise command arrangements. National caveats — restrictions placed by individual nations on how their forces may be employed — can significantly limit operational flexibility. Research into recent NATO-led operations suggests that mission success correlates more strongly with the quality of liaison mechanisms and shared situational awareness than with formal command hierarchy per se. This finding has prompted renewed emphasis on the development of common operational pictures and real-time information sharing at the operational and tactical levels.", question: "What does the cited research finding imply about operational priorities?", options: ["Formal hierarchy is irrelevant in modern multinational operations and should be abandoned outright in favour of consensus.", "National caveats should be eliminated entirely to achieve unity of command across every coalition contingent.", "Traditional command theory has been fully discredited by recent operational experience in coalition environments.", "Investment in information exchange may yield greater returns than reorganising command structures."], answer: 3, ex: "The finding is that liaison and shared awareness correlate more strongly than formal hierarchy — implying resources should flow to the former. Option D paraphrases this as 'information exchange may yield greater returns than reorganising command'. A overstates (the text says 'more strongly than', not 'instead of'). B is unrelated to the finding. D overstates ('renewed emphasis' ≠ 'fully discredited'). The trap is option A: surface readers may conflate 'correlates more strongly than' with 'is irrelevant'." },
    { topic: "Strategic communications", passage: "Information operations have become a critical dimension of modern conflict. State and non-state actors increasingly employ disinformation campaigns to undermine adversary decision-making, erode public trust, and create confusion in target populations. Social media platforms have amplified the reach and speed of these campaigns. The alliance has established specialised centres to monitor and counter hostile information activities. Effective response requires not only technical capabilities to detect and identify the origin of disinformation, but also the development of resilient information ecosystems within member societies. Public education in media literacy is increasingly recognised as a strategic security priority.", question: "What broader argument does the passage advance about countering disinformation?", options: ["Technical detection capabilities alone are insufficient; societal resilience matters equally.", "Social media platforms must be regulated to prevent disinformation spread.", "Specialised centres should be expanded across all member states.", "Decision-making processes must be insulated from public opinion to prevent manipulation."], answer: 0, ex: "The text argues effective response requires 'not only technical capabilities... but also the development of resilient information ecosystems' — option A captures both pillars. B is not advocated in the text. C is over-extrapolation. D inverts the logic (the public is to be educated, not insulated). The key skill: recognising 'not only X but also Y' as identifying paired requirements." },
    { topic: "Special operations forces", passage: "Special operations forces are characterised by their selection criteria, training intensity, and operational autonomy. They are typically employed in roles unsuitable for conventional forces, including direct action against high-value targets, special reconnaissance, military assistance to partner forces, and counter-terrorism. Their value derives from the ability to achieve strategic effects with limited footprints. However, the same autonomy that makes them effective creates challenges for oversight and integration with broader operational plans. Recent doctrine emphasises the need for clear boundaries between special operations and conventional military activities, while preserving the flexibility that makes such forces uniquely effective. The balance is delicate and remains the subject of ongoing debate within alliance forums.", question: "Which statement best characterises the central tension described in the passage?", options: ["Selection criteria for special forces are too restrictive to meet operational demand across the full spectrum of contemporary contingencies.", "The very qualities that produce operational effectiveness simultaneously generate institutional difficulties.", "Conventional forces and special forces increasingly compete for the same missions across overlapping operational areas.", "Counter-terrorism operations have eclipsed traditional special operations roles in budgetary and doctrinal priority."], answer: 1, ex: "'The same autonomy that makes them effective creates challenges' — option B captures this paradoxical relationship in different words. A, C, and D are unmentioned plausibilities. The skill tested here: recognising 'X is both the strength and the source of difficulty' as a thematic structure, without keyword cues." },
    { topic: "Maritime security", passage: "Maritime security operations encompass a range of activities aimed at preserving freedom of navigation and protecting commercial shipping from threats including piracy, smuggling, and terrorism. The alliance's Operation Sea Guardian in the Mediterranean exemplifies this approach. The operation conducts maritime situational awareness, supports counter-terrorism activities, and contributes to capacity-building for partner navies. Coordination with European Union missions and other international actors is essential, given the multiplicity of authorities operating in shared waters. The maritime domain presents distinctive challenges: vast areas to be monitored, the international legal regime governing the seas, and the variety of actors operating in maritime space. Effective operations therefore depend not merely on naval assets but on sustained legal frameworks and inter-organisational arrangements.", question: "What does the passage suggest about the conduct of maritime security?", options: ["Naval force levels are the primary determinant of operational success.", "Legal frameworks have become obstacles to effective maritime security.", "Operations cannot succeed through military assets alone.", "Counter-piracy has displaced counter-terrorism as the principal focus."], answer: 2, ex: "'Effective operations therefore depend not merely on naval assets but on sustained legal frameworks and inter-organisational arrangements' — option C paraphrases this. A is contradicted ('not merely on naval assets'). B inverts the relationship (legal frameworks are described as necessary, not as obstacles). D is unmentioned. Surface matching fails: the answer doesn't reuse 'legal', 'naval', or 'inter-organisational'." },
    { topic: "Stabilisation operations", passage: "Stabilisation operations seek to create the conditions for sustainable peace following conflict. They typically combine security activities with political, economic, and developmental components. Experience from operations in the Balkans, Iraq, and Afghanistan has demonstrated that purely military approaches are insufficient to address the underlying causes of instability. The concept of comprehensive approach emerged from these experiences, emphasising integrated civilian-military action under unified strategic direction. However, implementing this approach in practice has proved challenging. Civilian agencies and military forces operate under different cultures, timelines, and authorities. Genuine integration requires not only structural arrangements but also shared understanding of the operational environment and the desired end state.", question: "What lesson does the passage draw from operations in the Balkans, Iraq, and Afghanistan?", options: ["Military operations should be conducted independently of civilian agencies.", "Civilian agencies should adopt military timelines and authority structures.", "Unified strategic direction has been successfully achieved in recent operations.", "Stabilisation requires action across domains beyond the purely military."], answer: 3, ex: "The text states 'purely military approaches are insufficient' and stabilisation requires 'security, political, economic, and developmental components'. Option D paraphrases this as 'across domains beyond the purely military'. A reverses the lesson. B reverses who adapts to whom. C contradicts 'has proved challenging'. No option reuses 'comprehensive' or 'integration'." },
    { topic: "Ballistic missile defence", passage: "The alliance's ballistic missile defence capability is designed to protect alliance territory and populations against missile threats from outside the Euro-Atlantic area. The system integrates contributions from multiple member nations, including radar installations, interceptor missiles, and command and control elements. The capability has been declared operational and continues to be enhanced through ongoing investment. Russia has consistently characterised the system as a strategic threat, despite alliance assurances that it is not directed against Russian forces and lacks the technical capability to intercept Russian intercontinental missiles. This dispute has contributed to the deterioration of relations between the alliance and Russia, with implications extending beyond missile defence into broader questions of strategic stability in Europe.", question: "How does the passage characterise the disagreement over missile defence?", options: ["It serves as a symptom and accelerant of wider strategic friction rather than an isolated dispute.", "It reflects a genuine technical disagreement about the system's interception capabilities against intercontinental missiles.", "It has been substantially resolved in recent years through repeated alliance assurances given directly to Russia.", "It centres principally on disputes over the precise geographical placement of forward radar installations in the east."], answer: 0, ex: "'Implications extending beyond missile defence into broader questions of strategic stability' — option A captures this as 'symptom and accelerant of wider strategic friction'. B is wrong because the text says assurances were given (suggesting the technical dispute is not genuine). C contradicts 'deterioration'. D is unmentioned. The skill: recognising that a specific dispute can be a proxy for broader tensions." },
    { topic: "Capability development", passage: "The alliance's capability development priorities reflect the evolving security environment. Recent emphasis has focused on areas including cyber defence, space situational awareness, artificial intelligence, and resilience against hybrid threats. These priorities recognise that future conflicts are likely to involve simultaneous challenges across multiple domains, including those previously considered peripheral to traditional military operations. Investment decisions are guided by the alliance defence planning process, which seeks to ensure that the necessary capabilities exist to fulfil the core tasks of collective defence, crisis management, and cooperative security. National contributions to these capabilities are coordinated through agreed targets, although implementation has been uneven across member states.", question: "What does the passage suggest about future conflict?", options: ["It will be confined to traditional military domains.", "It is expected to unfold concurrently in arenas once regarded as marginal.", "It will primarily involve cyber and space rather than land or sea.", "It can be addressed through the existing defence planning process without modification."], answer: 1, ex: "'Simultaneous challenges across multiple domains, including those previously considered peripheral' — option B paraphrases 'previously considered peripheral' as 'once regarded as marginal'. A directly contradicts the text. C overstates: the new domains supplement rather than replace traditional ones. D is contradicted by 'uneven implementation'. Surface matching fails: no use of 'peripheral', 'cyber', 'space'." },
    { topic: "Counter-terrorism cooperation", passage: "Counter-terrorism cooperation within the alliance has evolved significantly since the 2001 attacks on the United States. The alliance's role complements that of national authorities and other international bodies, focusing primarily on intelligence sharing, capability development, and partnership with countries facing terrorist threats. The alliance maintains a counter-terrorism action plan and conducts regular exercises to test collective responses. However, primary responsibility for counter-terrorism remains with national governments, reflecting both legal frameworks and the predominantly domestic nature of many terrorist threats. The challenge of balancing security imperatives with civil liberties has been particularly acute in democratic societies, where intrusive surveillance powers face legal and political constraints absent in authoritarian regimes.", question: "What can be inferred about why the alliance plays a supporting rather than leading role in counter-terrorism?", options: ["The alliance lacks the technical and intelligence capability to lead counter-terrorism efforts independently.", "Member states have effectively refused to share sensitive intelligence at the multilateral alliance level.", "Many terrorist threats arise from and operate within domestic jurisdictions where national law applies.", "Counter-terrorism is not formally listed as a core task of the alliance in its founding documents."], answer: 2, ex: "The text states primary responsibility remains national 'reflecting both legal frameworks and the predominantly domestic nature of many terrorist threats'. Option C reformulates this as 'domestic jurisdictions where national law applies'. A is not stated. B contradicts 'intelligence sharing'. D is not in the text. The reader must connect 'domestic nature' + 'legal frameworks' to infer jurisdictional logic." },
    { topic: "Defence industrial cooperation", passage: "Defence industrial cooperation among alliance members has long been promoted as a means to enhance interoperability, reduce costs, and strengthen the technological base. Joint procurement programmes for major equipment have produced both successes and difficulties. Successful programmes have delivered advanced capabilities at affordable cost while building lasting industrial partnerships. Less successful efforts have been hampered by divergent national requirements, industrial protectionism, and political pressures to maintain domestic manufacturing capacity. Recent initiatives have sought to address these obstacles through more flexible cooperation frameworks. Whether these will produce sustained improvements remains uncertain, although the imperative of maximising defence resources amid competing demands provides strong motivation for continued effort.", question: "What does the passage imply about the prospects for future industrial cooperation?", options: ["Cooperation will inevitably succeed given the urgency of resource constraints.", "Past failures suggest cooperation efforts should be abandoned.", "Industrial protectionism has been definitively overcome through recent reforms.", "Outcomes are not assured, but pressures favour continued attempts."], answer: 3, ex: "'Whether these will produce sustained improvements remains uncertain, although the imperative... provides strong motivation' — option D captures the dual claim: uncertain outcome but strong driver. A overstates ('inevitably'). B is contradicted by 'continued effort'. C contradicts 'remains uncertain'. The reader must hold a balanced inference of uncertainty + motivation." },
    { topic: "Partnership programmes", passage: "The alliance maintains formal partnership relationships with countries beyond its membership, ranging from comprehensive frameworks to more limited arrangements with individual nations. These relationships serve multiple purposes, including enhancing security cooperation, building interoperability with potential coalition contributors, and projecting stability beyond the immediate Euro-Atlantic area. Partner nations have made significant contributions to alliance operations in places such as Afghanistan and Kosovo. The political dimensions of partnerships have, however, become increasingly complex as the geopolitical environment has shifted. Some partnerships face pressure from competing strategic relationships, while others have evolved towards closer integration, including potential pathways to membership.", question: "What does the passage suggest has changed about partnerships?", options: ["The geopolitical context surrounding them has become more demanding.", "Their original purposes have been replaced by new ones.", "They are now governed by simpler political dynamics than in the past.", "Partner nations have ceased to contribute to alliance operations."], answer: 0, ex: "'The political dimensions of partnerships have... become increasingly complex as the geopolitical environment has shifted' — option A paraphrases this as 'geopolitical context... more demanding'. B misreads — purposes are unchanged. C reverses the direction of change. D contradicts the past tense statement about contributions. Surface matching fails: no use of 'complex', 'political', 'geopolitical'." },
    { topic: "NATO operations — lessons learned process", passage: "The alliance's lessons learned process seeks to identify, analyze, and disseminate insights from operational experience to improve future performance. Following each major operation, specialist teams conduct systematic reviews examining what worked well and what did not. These reviews incorporate perspectives from multiple levels of command and from different national contingents to ensure a comprehensive understanding. However, the process faces inherent challenges. Organizational cultures within military institutions may resist acknowledging shortcomings, particularly when such acknowledgments could reflect poorly on senior leadership. Career incentives can discourage candid assessment of difficulties encountered during operations. Moreover, even when lessons are properly identified, translating them into changes in doctrine, training, or procurement often proves difficult due to institutional inertia and resource constraints. The most valuable lessons, therefore, are those that not only identify problems but also secure institutional commitment to implement solutions.", question: "What does the passage suggest is the most significant obstacle to organizational learning?", options: ["The difficulty of conducting systematic reviews across multiple command levels.", "Cultural and incentive structures that discourage honest evaluation of operational failures.", "The absence of specialist teams qualified to analyze complex operational experiences.", "Resource limitations that prevent the implementation of identified improvements."], answer: 1, ex: "The passage identifies 'organizational cultures... resist acknowledging shortcomings' and 'career incentives can discourage candid assessment' — these cultural/structural impediments occur before the implementation phase. Option B captures these twin barriers. A is not framed as an obstacle (reviews do incorporate multiple perspectives). C contradicts the text (specialist teams exist). D is real but positioned as one of several downstream challenges, not the primary obstacle. Level 3: distinguishing root causes from symptoms." },
    { topic: "Strategic partnerships — political dimensions", passage: "The alliance's partnerships with non-member states have historically served both security and political functions. From a security perspective, partnerships enhance operational effectiveness by building interoperability with nations that may contribute to coalition operations. Politically, partnerships serve as mechanisms for projecting stability into neighboring regions and for demonstrating the alliance's openness to cooperation beyond its formal membership. However, the political utility of partnerships has become more complex in recent years. Some partner nations face domestic pressure from constituencies that view close association with the alliance as compromising national sovereignty. Other partnerships have been strained by the partner nation's development of alternative security relationships with powers whose interests sometimes diverge from those of the alliance. These tensions highlight the distinction between formal partnership frameworks and the actual depth of cooperation that can be sustained given evolving political circumstances.", question: "What complication in partnership relationships does the passage identify?", options: ["Partners increasingly lack the military capabilities needed for meaningful operational contribution.", "The formal structure of partnerships has become too rigid to accommodate political change.", "Political pressures within and beyond partner states can limit the extent of practical cooperation.", "The alliance has expanded partnerships too rapidly to maintain quality relationships."], answer: 2, ex: "The passage describes two sources of strain: domestic pressure in partner nations ('compromising national sovereignty') and alternative security relationships with other powers. Option C captures both: 'political pressures within and beyond'. A is not mentioned (the passage affirms operational effectiveness, not capability gaps). B inverts the logic (the passage notes frameworks don't guarantee actual cooperation depth, but doesn't call them 'too rigid'). D is unmentioned. The distinction to grasp: formal vs. actual cooperation depth." },
    { topic: "Multinational exercises — training objectives", passage: "Large-scale multinational exercises serve multiple training objectives beyond the development of tactical proficiency. They provide opportunities to test command and control procedures across different national forces, identify interoperability challenges in equipment and communications, and practice logistical coordination in a complex operational environment. Perhaps more significantly, such exercises build personal relationships among officers from different nations who may later serve together in actual operations. The informal networks that develop during exercises can prove as valuable as formal coordination mechanisms when unanticipated challenges arise during real-world missions. Critics of large exercises argue that the substantial resources required could be better invested in more frequent, smaller-scale training events focused on specific capabilities. Proponents counter that the complexity inherent in large multinational exercises cannot be replicated in smaller settings, and that exposure to this complexity is itself a critical training objective.", question: "What assumption underlies the critics' position on exercise design?", options: ["That tactical proficiency is more important than relationship-building among officers.", "That formal coordination mechanisms are sufficient without informal professional networks.", "That interoperability challenges are less significant than command and control procedures.", "That smaller exercises can deliver equivalent training value with greater resource efficiency."], answer: 3, ex: "Critics argue resources 'could be better invested in more frequent, smaller-scale training' — the implicit assumption is smaller exercises yield comparable or superior value per resource unit invested. Option D captures this efficiency logic. A is not the critics' claim (they may value relationships but prioritize frequency). B misreads (critics don't address informal networks; proponents do). C is unrelated to the critics' argument. Level 3 skill: inferring unstated assumptions from stated positions." },
    { topic: "Technology integration — digital transformation", passage: "The integration of advanced digital technologies into military operations promises substantial improvements in situational awareness, decision-making speed, and precision. Artificial intelligence applications can process vast quantities of sensor data far more rapidly than human analysts. Autonomous systems can perform dangerous missions with reduced risk to personnel. However, the adoption of these technologies introduces new vulnerabilities. Adversaries can exploit weaknesses in software or cyber defenses to compromise systems. Over-reliance on automated systems may erode the judgment and intuition that experienced personnel bring to complex operational problems. There is also concern that the pace of technological adoption in some allied nations significantly exceeds that in others, potentially creating disparities in capability that undermine interoperability. Effective integration therefore requires not merely acquiring new technologies but developing appropriate doctrine for their employment and establishing safeguards against their misuse or failure.", question: "What does the passage suggest about successful technology adoption in military operations?", options: ["It requires complementary developments in employment doctrine and protective measures.", "It depends primarily on maintaining parity in technological capabilities across all allied forces.", "It should be delayed until automated systems can fully replicate human judgment.", "It is hindered mainly by adversary capabilities to exploit system vulnerabilities."], answer: 0, ex: "'Effective integration... requires not merely acquiring new technologies but developing appropriate doctrine for their employment and establishing safeguards' — option A paraphrases 'doctrine' and 'safeguards' as 'employment doctrine and protective measures'. A overstates (disparities are a concern, but parity is not stated as the primary dependency). C contradicts the text (the passage worries about over-reliance but doesn't advocate delay). D identifies one risk among several, not the main hindrance. The skill: identifying multi-dimensional requirements for success." },
    { topic: "Legal frameworks — operational constraints", passage: "International humanitarian law imposes obligations on military forces that can create tension with operational objectives. The principles of distinction and proportionality require forces to differentiate between combatants and civilians and to ensure that incidental civilian harm is not excessive in relation to the concrete military advantage anticipated. In practice, applying these principles demands detailed intelligence about the operational environment, sophisticated targeting procedures, and real-time legal advice during operations. Critics argue that strict adherence to legal norms places forces at a disadvantage when adversaries operate without similar constraints. Supporters of robust legal frameworks counter that compliance enhances the legitimacy of operations, which is itself a strategic asset. Moreover, they argue, abandoning legal constraints would undermine the very values that democratic societies seek to defend. This debate reflects deeper tensions between military effectiveness and ethical commitment.", question: "What fundamental disagreement do the two positions described in the passage express?", options: ["Whether international humanitarian law should apply to military forces of democratic nations.", "Whether operational advantage or adherence to values should take precedence when they conflict.", "Whether forces possess sufficient intelligence to comply with legal targeting requirements.", "Whether adversaries' failure to observe legal norms justifies reciprocal violations."], answer: 1, ex: "Critics focus on operational disadvantage ('places forces at a disadvantage'); supporters prioritize legitimacy and values ('strategic asset', 'values that democratic societies seek to defend'). The core disagreement is whether effectiveness or ethical commitment should govern when they pull in opposite directions. Option B captures this axis. A and D overstate (no one argues democratic forces should be exempt or should reciprocate violations). C misses the normative disagreement (it's about factual capability). Level 3: identifying the conceptual axis along which two positions diverge." },
    { topic: "Crisis response — decision-making speed", passage: "Consensus-based decision-making within the alliance ensures that all member states have a voice in determining collective action. This inclusive approach protects national sovereignty and builds political legitimacy for alliance operations. However, the requirement for consensus can produce delays during fast-moving crises where rapid response may be essential to prevent escalation or protect threatened populations. Some analysts propose delegating greater authority to senior military commanders or to a subset of member states during emergencies. Others caution that bypassing full consultation, even in urgent circumstances, risks fracturing alliance unity and undermining the political foundation upon which military cooperation depends. Recent proposals have sought middle ground through pre-authorized response options that allow rapid initial action followed by subsequent political ratification. The viability of such arrangements remains untested in actual crisis conditions.", question: "What trade-off lies at the heart of the debate over crisis decision procedures?", options: ["Between military expertise and political judgment in operational planning.", "Between defending threatened populations and preserving alliance resources.", "Between the speed of response and the inclusiveness of decision-making.", "Between pre-authorized options and post-crisis political ratification."], answer: 2, ex: "Consensus ensures inclusiveness but 'can produce delays during fast-moving crises where rapid response may be essential'. Option C captures the two competing goods: speed vs. inclusiveness. A is not the trade-off (both sides involve political decision-making). B is unmentioned. D misreads (pre-authorization is proposed as a solution, not one pole of the trade-off). Level 3: recognizing structural trade-offs within institutional design." },
    { topic: "Interoperability — standardization challenges", passage: "Achieving interoperability among alliance forces requires compatibility in equipment, procedures, and training. Standardization of equipment simplifies logistics and maintenance while ensuring that systems from different nations can operate together. However, complete standardization is often impractical due to divergent national requirements, existing inventories that would be costly to replace, and domestic industrial considerations. Nations understandably seek to preserve domestic manufacturing capacity for defense equipment, both for economic reasons and to maintain sovereign capability in critical areas. Consequently, the alliance has pursued a policy of pursuing interoperability through agreed standards for interfaces and communication protocols rather than requiring identical equipment across all forces. This approach allows national diversity in equipment choices while ensuring that different systems can work together when required. The challenge lies in enforcing adherence to agreed standards when national procurement decisions are made independently.", question: "Why does the passage suggest complete equipment standardization is unrealistic?", options: ["Because alliance procurement procedures cannot accommodate the diverse preferences of member states.", "Because agreed communication protocols have proven more effective than hardware uniformity.", "Because existing equipment inventories have reached the end of their operational service life.", "Because economic and sovereignty considerations lead nations to retain distinct manufacturing bases."], answer: 3, ex: "The passage lists 'divergent national requirements, existing inventories that would be costly to replace, and domestic industrial considerations' plus 'preserve domestic manufacturing capacity... for economic reasons and to maintain sovereign capability'. Option D synthesizes these as 'economic and sovereignty considerations... distinct manufacturing bases'. A is a procedural constraint not mentioned. B misreads (protocols are the solution, not the reason standardization is impractical). C contradicts the text (costly to replace existing inventories, not that they've reached end-of-life). Level 3: synthesizing multiple stated reasons into a higher-order explanation." },
    { topic: "Force structure — readiness vs. capacity trade-offs", passage: "Alliance force planners confront a persistent tension between maintaining high-readiness forces that can respond rapidly to crises and developing the overall capacity necessary for sustained operations. High-readiness forces require intensive training, modern equipment, and personnel who can deploy on short notice. These demands are resource-intensive. Prioritizing readiness therefore limits the total number of personnel and units that can be maintained within a given defense budget. Conversely, emphasizing overall capacity allows larger forces but may result in lower readiness levels across the force as a whole. Historical experience suggests that both attributes are necessary: high-readiness forces for initial response and larger capacity forces for reinforcement and sustainment. The optimal balance depends on the strategic environment and the specific threats that forces may face. In practice, member nations vary considerably in how they balance these competing demands, reflecting different threat perceptions and resource constraints.", question: "What does the passage imply about force structure decisions?", options: ["They involve choosing between competing goods rather than selecting an objectively correct answer.", "They should prioritize high-readiness forces because initial response is most critical.", "They are primarily constrained by available defense budgets rather than strategic considerations.", "They have been resolved effectively through alliance-level coordination among member states."], answer: 0, ex: "'The optimal balance depends on the strategic environment and the specific threats' and 'member nations vary considerably' — this indicates there's no universal right answer, just different reasonable choices based on context. Option A captures this as 'competing goods rather than objectively correct'. A takes one side of a false binary. C overstates (resources are a constraint, but strategic factors also matter). D contradicts 'member nations vary considerably'. The inference: recognizing that structural trade-offs preclude definitive solutions." },
    { topic: "Leadership development — officer education", passage: "Professional military education for officers has traditionally emphasized technical competence in military tactics and operations. However, the contemporary security environment demands a broader skill set. Officers at senior levels must understand political context, engage effectively with civilian authorities and international partners, and make decisions in situations where military and political considerations are deeply intertwined. Some defense establishments have responded by incorporating more political science, international relations, and ethics into officer education curricula. Critics worry that broadening the curriculum dilutes the focus on core military competencies and that officers educated in this manner may be less prepared for the fundamental task of leading in combat. Proponents argue that technical military skills, while essential, are insufficient for the complex leadership demands of modern operations, particularly those involving coalition partners and civilian populations. The debate reflects broader questions about the proper role of military institutions in democratic societies.", question: "What concern do critics of broadened military education express?", options: ["That officers will become overly involved in political decision-making beyond their professional role.", "That dedicating curriculum time to non-military subjects may compromise proficiency in essential military skills.", "That civilian authorities will lose confidence in military officers who study political science.", "That coalition operations require different educational preparation than traditional military training."], answer: 1, ex: "Critics 'worry that broadening the curriculum dilutes the focus on core military competencies' and officers 'may be less prepared for the fundamental task of leading in combat'. Option B paraphrases 'dilutes the focus' as 'compromise proficiency'. A is plausible but not stated. C is implausible and unmentioned. D misreads (coalition ops are cited as a reason to broaden, not a concern about broadening). The skill: distinguishing what critics actually claim from adjacent concerns they might have." },
    { topic: "Coalition operations — national caveats", passage: "National caveats — restrictions that individual nations place on how their forces may be employed in coalition operations — are an unavoidable feature of multinational cooperation. They reflect legitimate concerns: domestic political constraints, assessment of operational risk, and interpretation of international legal obligations. Yet extensive caveats can significantly complicate planning and curtail the flexibility available to coalition commanders. Differing rules on use of force, intelligence sharing, or geographic limits produce a patchwork capability that resists coherent employment. Commanders prefer minimal restrictions; political leaders insist on retaining authority over their forces. Success therefore depends less on eliminating caveats — which is unrealistic — than on ensuring they are clearly understood by all participants and incorporated into planning from the outset.", question: "What does the passage suggest is essential for managing national caveats effectively?", options: ["Gradual removal of restrictions through political persuasion of contributing nations.", "Delegation of final authority over force employment to coalition military commanders.", "Transparent communication of limitations and their integration into operational planning.", "Standardisation of use-of-force rules across all national contingents."], answer: 2, ex: "'Success depends less on eliminating caveats... than on ensuring they are clearly understood by all participants and incorporated into planning from the outset' — option C paraphrases 'clearly understood' as 'transparent communication' and 'incorporated into planning' as 'integration into operational planning'. A contradicts 'eliminating caveats... is unrealistic'. B contradicts 'political leaders... insist on retaining authority'. D is desirable but not presented as the essential element. Level 3: identifying what the author treats as the practical solution vs. the ideal but unattainable." },
    { topic: "Hybrid Warfare Doctrine", passage: "Hybrid warfare erodes the war-peace divide by interleaving conventional force, irregular tactics, cyber action, economic coercion, and information manipulation. Unlike orthodox conflict, where the aggressor is identifiable and the armed-attack threshold reasonably clear, hybrid campaigns deliberately sit below that threshold, denying defenders a pretext to react. The targeted state finds itself responding to incidents each of which, in isolation, looks equivocal or attributable to proxies — yet which collectively advance a coherent strategic aim. This ambiguity is itself a weapon: by the time the pattern is undeniable, the aggressor may have secured significant gains while retaining plausible deniability. Effective response demands inter-agency coordination, robust attribution, and political willingness to act on imperfect intelligence — the last of which democracies, prizing legal certainty and public consent, find hardest to muster. Hence the recurring tension between escalation risk and strategic paralysis.", question: "According to the passage, what is the central strategic advantage hybrid actors exploit?", options: ["Their technological superiority over defending militaries", "Their readiness to escalate to open warfare ahead of expectations", "Their economic leverage relative to target states", "The deliberate equivocation that surrounds their actions"], answer: 3, ex: "本文の 'This ambiguity is itself a weapon' および 'deliberately sit below that threshold, denying defenders a pretext to react' から、曖昧性 = 戦略的利点という構造。A/B は本文で論じられず、C はハイブリッド戦の論理 (低閾値運用) と矛盾。 'equivocation' は 'ambiguity' のパラフレーズで、L3 では同義語認識が鍵。" },
    { topic: "Multinational Interoperability", passage: "The viability of multinational operations rests on interoperability, a notion that stretches well beyond hardware compatibility. While radio protocols and ammunition calibres draw most engineering attention, the subtler dimensions are procedural and cultural. Each national doctrine encodes a distinct history and political constraint set, surfacing in how commanders construe orders, calibrate risk, and approach civilians. A unit hemmed in by restrictive caveats may decline tasks another contingent would shoulder, fracturing unity of effort. English as the working tongue masks rather than resolves the gap: tactical precision routinely outstrips proficiency adequate for staff routine. Exercises help, yet rarely replicate trust accrued over months of shared operations, and frequent rotations curtail the maturation of working relationships.", question: "What does the author identify as the most underappreciated impediment to multinational interoperability?", options: ["Divergences in procedural conventions and embedded institutional culture", "Inadequate harmonisation of weapons systems and equipment across allies", "Underfunding of joint training infrastructure", "Smaller nations' unwillingness to commit substantive forces"], answer: 0, ex: "本文の 'the subtler dimensions are procedural and cultural' と 'how commanders construe orders, calibrate risk' から、手続き・文化の差が看過されていると論じている。B は技術面が 'draw most engineering attention' と既に注目されている点で本文と矛盾。C/D は本文に該当記述なし — もっともらしいが本文では論点にされていない distractor。" },
    { topic: "Cyber Deterrence", passage: "Deterrence in cyberspace bears little resemblance to its nuclear forerunner. Nuclear logic rests on credible threats of unambiguous, catastrophic retaliation against an identifiable aggressor. Cyber operations, conversely, tend to be covert, reversible and incremental — an intruder may exfiltrate data, briefly disrupt systems, or pre-position dormant tools for later exploitation, each act carrying its own evidentiary threshold. Attribution, where attainable, typically takes weeks and seldom yields proof robust enough to justify proportionate response under prevailing legal norms. Retaliation itself is constrained by digital interdependence: a counterstroke may cascade into uninvolved networks. Hence some scholars now favour resilience and persistent engagement over classical deterrence — accepting that intrusions will occur and concentrating on consequence-management while continuously contesting adversaries in the domain.", question: "What does the passage primarily argue about classical deterrence theory in cyberspace?", options: ["It can be salvaged once attribution capabilities mature", "It is poorly tailored to the prevailing conditions of cyber operations", "It transfers cleanly because cyber effects are reversible", "It must be discarded in favour of unrestrained offensive cyber action"], answer: 1, ex: "'Deterrence in cyberspace bears little resemblance to its nuclear forerunner' と最終文の 'resilience and persistent engagement over classical deterrence' から、古典的抑止論は環境に合わないという主張。A は本文の論調と逆 ('seldom yields proof' = 帰属能力の改善で済まない)。D は 'favour resilience' という穏健な提案を 'unrestrained offensive' と誇張、C は cyber と nuclear の対比を完全に逆転している。" },
    { topic: "Information Warfare", passage: "Contemporary information warfare leverages fragmented media consumption and the algorithmic amplification of emotionally charged content. Earlier propaganda required broadcast infrastructure or compliant newspapers; today's operations reach targeted audiences via platforms whose commercial logic privileges engagement over veracity. Adversaries rarely need to fabricate narratives wholesale — they locate existing social fault lines and amplify voices on each side, deepening polarisation without necessarily favouring any single outcome. The objective is often not to persuade audiences of a particular truth but to corrode their confidence that any shared truth is attainable. This asymmetry favours authoritarian actors, whose own populations have limited capacity to push back, while democracies confront the bind of defending their information space without imposing restrictions that themselves erode democratic norms. The most promising responses combine societal resilience with transparent, targeted attribution.", question: "According to the passage, what does the author identify as a common goal of modern information operations?", options: ["Securing the election of a specific political candidate in target nations", "Displacing existing media outlets with state-controlled alternatives", "Corroding the audience's conviction that any shared truth is reachable", "Inciting direct violence against government institutions"], answer: 2, ex: "本文の 'corrode their confidence that any shared truth is attainable' をほぼ直接パラフレーズ。A は 'without necessarily favouring any single outcome' により否定。B/D は本文に該当記述なし。L3 では「特定の真実を売り込む」のではなく「真実への信頼を破壊する」という反転構造の把握が鍵。" },
    { topic: "Strategic Logistics", passage: "Strategic logistics has resurfaced as a central planning concern after years of expeditionary missions against under-resourced foes lulled planners into trusting their supply lines. The prospect of peer-level conflict has driven home that projecting force across thousands of kilometres demands not only stockpiles but resilient transport corridors, host-nation accords, and industrial throughput that cannot be conjured at short notice. Decades of just-in-time inventory practice, borrowed from commercial supply chains, have hollowed reserves of munitions, spares, and basic consumables. Replenishment now hinges on industrial bases thinned by consolidation and offshoring, with key components sometimes sourced from states whose wartime posture is unpredictable. Vulnerability of sea and air corridors to long-range precision strike further constrains options. Allied countermoves on stockpile pooling and coordinated investment exist, but national procurement preferences favouring domestic employment over coalition coherence keep progress patchy.", question: "What is the author's principal worry about contemporary military logistics?", options: ["The fiscal cost of maintaining outsized peacetime stockpiles across multiple categories of munitions", "Allies' chronic failure to align on common procurement standards for shared platforms and consumables", "Excessive reliance on automated logistics systems vulnerable to disruption during contested operations", "The compounding effect of lean inventories and an attenuated production base"], answer: 3, ex: "本文の 'just-in-time inventory practice... hollowed reserves' と 'industrial bases thinned by consolidation and offshoring' の両方が並列で問題視されており、その重なりが中心的懸念。A は逆方向の懸念で本文と齟齬、B は本文では言及あるが '中心的' とは扱われていない distractor、C は本文に該当記述なし。" },
    { topic: "Space Domain Security", passage: "Space has shifted from a realm of strategic stability — where mutual reliance on satellites discouraged interference — to one of active contestation. The proliferation of counter-space capabilities, from kinetic interceptors to directed-energy weapons and cyber intrusion, has eroded the implicit norms that once governed orbital behaviour. Kinetic engagement is particularly fraught: debris produced by a single intercept can imperil satellites at comparable altitudes for decades, generating a tragedy-of-the-commons dynamic that even adversaries should rationally seek to avoid. Yet rational calculation does not always prevail, and demonstration tests have repeatedly added to the orbital debris population despite international concern. Commercial proliferation of small satellites complicates the picture further. Treaty frameworks designed for the early space age have not kept pace, and new-agreement efforts founder on disputes over which capabilities to restrict and how compliance is to be verified when dual-use technology is the norm.", question: "What does the passage suggest is paradoxical about anti-satellite testing?", options: ["The resulting debris can imperil the testing nation's own satellites", "The tests are conducted by states that publicly denounce them", "The tests consume more resources than the targeted satellites are worth", "The tests are barred by treaties that every spacefaring state has ratified"], answer: 0, ex: "本文の 'tragedy-of-the-commons dynamic that even adversaries should rationally seek to avoid' と 'debris... can imperil satellites at comparable altitudes for decades' から、自国衛星も危険にさらす逆説が読み取れる。D は本文の 'frameworks... have not kept pace' と矛盾、B/C は本文に該当記述なしの distractor。L3 では論理関係 (因果と逆説) の把握が問われる。" },
    { topic: "Counter-Insurgency Strategy", passage: "Counter-insurgency doctrine has cycled through successive refinements, each iteration mining the prior campaign for lessons while only partly anticipating the next. The population-centric model prevalent in the early 2000s held that civilian protection and host-nation legitimacy were the decisive variables in defeating an insurgency. The framework yielded tactical wins, but its limits surfaced quickly. Where the host government was systemically corrupt or seen as favouring one community, civilian protection failed to translate into political consolidation. External forces could hold terrain yet could not manufacture legitimacy for regimes whose own conduct corroded it. Subsequent analyses underline that nominally unified armed opposition often masks factions with divergent aims and varying receptiveness to negotiation — implying that even masterful military action cannot settle conflicts rooted in unresolved political grievance. The external role therefore migrates from defeating insurgents toward shaping conditions in which political processes can run.", question: "What is the principal limitation of the population-centric approach as described in the passage?", options: ["Its disproportionate burden on personnel and equipment over extended operational deployments", "Its inability to substitute for shortcomings in host-nation political life", "Its incompatibility with conventional military doctrine taught at most service academies", "Its dependence on advanced technologies that adversaries readily counter with low-cost measures"], answer: 1, ex: "本文の 'External forces could hold terrain yet could not manufacture legitimacy' を 'substitute for shortcomings in host-nation political life' とパラフレーズ。A/C/D は本文に該当記述なし — もっともらしいが本文の論証構造ではない。L3 では本文の論理関係 (原因→限界) を見抜くのが鍵。" },
    { topic: "Defence Industrial Base", passage: "The vitality of a nation's defence industrial base carries direct strategic weight that reaches well beyond peacetime budgeting. A diversified, technologically deep base enables swift adaptation to emerging threats, sustains domestic expertise in critical technologies, and curtails dependencies an adversary might exploit in crisis. The economic logic shaping recent industrial policy has, however, pulled the opposite way — favouring concentration among a few prime contractors, globally distributed supply chains, and migration of specialised manufacturing to lower-cost states. The result, across many allied nations, is a base capable of producing sophisticated platforms in small numbers but ill-suited to rapid mobilisation. Recent conflicts illustrate the cost: munitions consumption has outpaced production by an order of magnitude, with replacement lead times stretching across years. The fundamental challenge is to reconcile the efficiency markets reward in peacetime with the redundancy that strategic prudence demands.", question: "What tension does the passage identify at the heart of defence industrial policy?", options: ["Between national security secrecy and the imperative of international cooperation", "Between domestic employment objectives and the technical quality of products", "Between the cost efficiency markets reward and the redundancy security requires", "Between civilian oversight and military operational requirements"], answer: 2, ex: "本文の最終文 'reconcile the efficiency markets reward in peacetime with the redundancy that strategic prudence demands' をほぼ直接パラフレーズ。これが論証の核心。A/B/D は本文では言及されておらず、もっともらしいだけの distractor。L3 では文書全体の主題テンションを把握する力が問われる。" },
    { topic: "Alliance Burden Sharing", passage: "Burden-sharing disputes are coeval with alliances, yet their salience has lately grown as relative economic standings and threat perceptions among members have diverged. The simplest yardstick — defence outlay as a share of GDP — captures only one facet of contribution and can mislead in both directions. A state meeting the threshold may channel most of it into personnel costs that crowd out capability investment; another below the threshold may field exceptional forces, host strategic infrastructure, or contribute disproportionately to specific missions. Geography, historical memory and domestic political tolerance all shape what each member can plausibly offer. Treating compliance with a numeric target as the whole question generates resentment without closing capability gaps; abandoning any metric, conversely, invites free-riding. The more productive debate concerns outcomes rather than inputs — whether the alliance collectively meets identified requirements, and whether each member contributes proportionate to its capacity and the alliance's needs.", question: "What does the author imply about using defence-spending percentages as the dominant measure of contribution?", options: ["It is the only objective benchmark realistically available to alliances", "It is dependable when applied uniformly across all members", "It should be supplanted entirely by counts of deployed personnel", "It collapses a multifaceted question into a single misleading figure"], answer: 3, ex: "本文の 'captures only one facet of contribution and can mislead in both directions' を 'collapses a multifaceted question into a single misleading figure' とパラフレーズ。C は 'productive debate centers on outcomes' に近いが 'entirely supplant' とまでは述べておらず誇張。A/B は本文の論調と逆。" },
    { topic: "Climate Security", passage: "The climate-security nexus is mediated through chains of effect that frustrate tidy causal claims, yet that complexity does not warrant treating the link as speculative. Direct effects — rising sea levels at coastal naval installations, training cycles disrupted by extreme weather — are increasingly visible and can be costed with reasonable confidence. Indirect effects are more consequential but harder to attribute: prolonged drought may compound agricultural failure, displacement, and resource competition, interacting with pre-existing political tensions to incubate or intensify conflict. Asking whether climate is the dominant cause in a given case is rarely the right question; more useful is to treat climate as a stress multiplier that shifts the probability distribution of adverse outcomes across many regions at once. Planning for this requires integration across previously siloed domains and a willingness to act on probabilistic assessments rather than wait for certainty the timescales do not permit.", question: "What does the author suggest is a more useful framing of the climate-security relationship?", options: ["Treating climate as a factor that raises the likelihood of adverse outcomes", "Establishing climate as the principal driver of contemporary conflicts", "Deferring climate considerations until causation has been definitively proven", "Confining analysis to direct physical effects on military installations"], answer: 0, ex: "本文の 'a stress multiplier that shifts the probability distribution of adverse outcomes' を 'a factor that raises the likelihood of adverse outcomes' とパラフレーズ。B は 'rarely the right question' と否定された見方、C は 'wait for certainty the timescales do not permit' を本文が明確に拒否、D は本文が「直接効果のみでは不十分」と論じている点と矛盾。" }
  ],
  4: [
    { topic: "Nuclear deterrence", passage: "The alliance's nuclear deterrence posture is predicated upon the principle that nuclear weapons will not be employed as a first resort but retains the right to do so under extreme circumstances threatening the survival of any member state. This deliberate ambiguity, enshrined in the concept of flexible response, serves to complicate adversarial calculations and thereby enhances deterrence. The deployment of tactical nuclear weapons in Europe under dual-key arrangements with selected allies represents both a political commitment and a tangible capability signal. Critics of the current posture contend that ambiguity may inadvertently lower the threshold for escalation and create dangerous miscalculations during crises. Proponents argue, conversely, that clarity in declaratory policy would undermine the very uncertainty upon which deterrence fundamentally depends. The debate has acquired renewed salience following recent crises in Eastern Europe and the explicit nuclear threats articulated by certain leaders during these conflicts.", question: "What underlying disagreement separates the two positions described in the passage?", options: ["Whether nuclear weapons should be retained at all within the alliance arsenal under any future contingency.", "Whether dual-key arrangements still provide adequate political control in a contested security environment.", "Whether tactical nuclear weapons should be progressively replaced with strategic ones for stability reasons.", "Whether predictability or unpredictability better serves the purpose of preventing conflict."], answer: 3, ex: "Critics worry ambiguity 'lowers the threshold' (i.e. favour clarity); proponents argue clarity 'undermines uncertainty' (i.e. favour ambiguity). The deep disagreement is whether predictability or its opposite enhances deterrence. Option D captures this as 'predictability or unpredictability'. A, B, C address peripheral matters not at the core of the disagreement. The Level 4 skill: identifying the conceptual axis along which two positions differ, even when neither position is fully stated in those terms." },
    { topic: "Alliance enlargement", passage: "The debate over the alliance's continued enlargement has intensified in the wake of recent acts of aggression in Europe. Proponents of an open-door policy invoke both the foundational principle of sovereign self-determination and the strategic rationale of extending the alliance's defensive perimeter to encompass states that share its values and interests. Opponents point to the destabilising effects of perceived encirclement and caution that enlargement may provoke disproportionate responses from revisionist powers seeking to preserve their declining sphere of influence. The accession of Finland in 2023 and Sweden in 2024 marked a historic shift in Northern European security architecture, demonstrating that the alliance retains the capacity to adapt to evolving geopolitical realities. These accessions, undertaken in response to aggression rather than despite it, fundamentally complicate the narrative that enlargement constitutes a primarily provocative act. The strategic implications, including expanded responsibilities for collective defence in the High North, will continue to shape planning for decades.", question: "What rhetorical effect does the passage attribute to the Nordic accessions?", options: ["They weaken a key claim used by those who object to extending alliance membership.", "They confirm the validity of the encirclement argument advanced by opponents of enlargement.", "They demonstrate that enlargement is now a matter of consensus among observers.", "They show that the alliance has reached the limits of its adaptive capacity."], answer: 0, ex: "'These accessions, undertaken in response to aggression rather than despite it, fundamentally complicate the narrative that enlargement constitutes a primarily provocative act' — the accessions undermine the opponents' argument. Option A paraphrases 'fundamentally complicate the narrative' as 'weaken a key claim'. B inverts the meaning. C overstates ('consensus' is not claimed). D contradicts 'capacity to adapt'. The Level 4 skill: tracking which argument is strengthened or weakened by a given event." },
    { topic: "Alliance narrative coordination", passage: "The strategic communications framework adopted by the alliance sought to address information asymmetries that had hitherto undermined cohesion among member states. By establishing a centralised narrative management protocol, the alliance aimed to preclude adversarial exploitation of internal disagreements while simultaneously reinforcing the credibility of its deterrence posture vis-à-vis potential aggressors. Implementation has proved more challenging than anticipated. Member states retain divergent national narratives shaped by distinct historical experiences and contemporary political imperatives. The proliferation of communication channels, including platforms outside traditional regulatory frameworks, has further complicated efforts to maintain consistent messaging. Notwithstanding these obstacles, recent initiatives suggest that incremental progress is achievable, particularly when coordinated responses to specific incidents demonstrate the practical value of collective action. The challenge remains balancing the operational requirements of effective communications with the democratic imperative of free expression.", question: "What fundamental tension does the passage identify as constraining the framework's success?", options: ["Between centralisation and the divergent technical capabilities of member states across the alliance.", "Between effective coordination of messaging and the openness inherent to democratic governance.", "Between member states' historical experiences and the contemporary political imperatives driving the framework.", "Between traditional broadcast media and the emerging digital communication platforms now in use."], answer: 1, ex: "The closing sentence — 'balancing the operational requirements of effective communications with the democratic imperative of free expression' — names this tension. Option B paraphrases 'free expression' as 'openness inherent to democratic governance' and 'operational requirements' as 'effective coordination of messaging'. C and D describe complicating factors but not the fundamental tension named in the closing sentence. A is unmentioned. Level 4 demands identifying which of several mentioned tensions the author treats as foundational." },
    { topic: "Multi-domain operations", passage: "Multi-domain operations represent a paradigmatic shift in how military campaigns are conceptualised and executed. Rather than treating air, land, sea, space, and cyber as parallel but largely independent domains, the framework seeks to exploit convergence — the simultaneous application of effects across domains to create dilemmas for the adversary that cannot be resolved by acting in any single domain. Air power, by virtue of its speed, reach, and flexibility, remains the principal enabler of cross-domain synergy. However, realising this potential demands a level of inter-service integration and digital interoperability that most allied nations are still developing. Some critics suggest that the construct, while intellectually compelling, risks obscuring rather than clarifying operational thinking by adding layers of complexity to already challenging coordination problems. Others argue that the framework merely articulates what skilled commanders have always sought to achieve, namely the integration of effects from all available capabilities to produce decisive outcomes.", question: "What position do the second group of critics described in the text appear to hold?", options: ["The framework introduces fundamentally new principles of warfare unknown to previous generations of commanders.", "Multi-domain integration cannot be achieved without significant institutional reform across every contributing service.", "The doctrine is essentially a formal restatement of long-standing operational practice.", "Air power should not be privileged over the other military domains in modern operations conducted at scale."], answer: 2, ex: "'The framework merely articulates what skilled commanders have always sought to achieve' — option C paraphrases 'merely articulates' as 'essentially a formal restatement' and 'always sought to achieve' as 'long-standing operational practice'. A inverts the position. B is a different argument unmentioned. D contradicts the passage's claim about air power's enabling role. Level 4 requires distinguishing between two critical positions and matching each to its proper paraphrase." },
    { topic: "Hybrid threat attribution", passage: "The challenge of attributing hostile actions in the contemporary security environment has acquired unprecedented complexity. Adversaries operating below the threshold of armed conflict deliberately exploit ambiguity to inhibit decisive collective response. Cyber operations conducted through chains of compromised infrastructure across multiple jurisdictions, disinformation campaigns disseminated through inauthentic networks, and economic coercion pursued through proxy entities all complicate traditional attribution frameworks. Even when technical attribution is achievable, the political will to publicly name responsible actors may be lacking, particularly when such acknowledgement implies obligations to respond. The alliance has invested in developing collective attribution mechanisms, recognising that the credibility of deterrence ultimately depends upon the demonstrated willingness to identify and respond to hostile actions. Yet the asymmetry between democratic constraints and authoritarian impunity continues to favour aggressors who can maintain plausible deniability while their victims navigate transparent legal processes.", question: "What deeper structural problem does the passage identify beyond the technical difficulty of attribution?", options: ["The financial cost of developing collective attribution mechanisms is prohibitive for most alliance members.", "Cyber infrastructure is too widely distributed across jurisdictions to be effectively monitored in real time.", "Economic coercion is intrinsically more difficult to attribute than cyber operations conducted from abroad.", "Procedural transparency of democracies creates a disadvantage their adversaries do not share."], answer: 3, ex: "'The asymmetry between democratic constraints and authoritarian impunity continues to favour aggressors' — option D paraphrases this as 'procedural transparency of democracies creates a disadvantage'. A is unmentioned. B and C are surface details, not the structural problem identified. Level 4 demands recognising the structural/systemic claim that sits above the operational details. Surface readers will be drawn to C because the passage discusses cyber infrastructure." },
    { topic: "Tailored deterrence", passage: "Contemporary deterrence theory has evolved considerably from its Cold War origins, when nuclear-centric models predominated. The current strategic environment requires conceptual frameworks capable of addressing simultaneous challenges from peer competitors, regional powers, and non-state actors operating across the full spectrum of conflict. Tailored approaches recognise that what deters a nuclear-armed great power may be entirely irrelevant against a transnational terrorist organisation, and that what credibly threatens an authoritarian regime may not affect a democratic adversary's calculations. This proliferation of deterrence relationships imposes substantial demands on intelligence, capabilities, and policymaking capacity. The integrated deterrence concept seeks to consolidate these multiple requirements within a unified framework. However, the practical implementation remains contested, with debates over the relative weight to be assigned different threats and the appropriate balance between conventional, nuclear, and non-kinetic instruments.", question: "What presumption underlying older deterrence models is challenged by the tailored approach?", options: ["That a single set of deterrence principles can apply uniformly across all adversaries.", "That nuclear weapons have lost their relevance in contemporary security and need replacement.", "That conventional capabilities are sufficient without nuclear backing in any plausible scenario.", "That deterrence relationships should be limited to peer competitors and ignore lesser actors."], answer: 0, ex: "Tailored deterrence is premised on the idea that different adversaries require different approaches — implicitly rejecting the universal applicability assumed by older models. Option A captures this presumption being challenged. B is not the claim. C reverses the logic. D restricts the scope incorrectly. Level 4 requires inferring what was implicitly assumed by the prior model that the new approach now rejects." },
    { topic: "Strategic stability and arms control", passage: "Strategic stability between nuclear-armed great powers has historically rested upon a combination of mutual vulnerability, transparency mechanisms, and arms control agreements that constrain destabilising capabilities. The progressive erosion of this architecture, evidenced by the lapse of several major treaties, has raised concerns about increased risk of miscalculation during crises. Emerging technologies, including hypersonic weapons, autonomous systems, and counterspace capabilities, complicate traditional concepts by compressing decision timelines and blurring distinctions between conventional and nuclear capabilities. Restoring elements of the previous architecture appears unlikely in the near term given current geopolitical tensions. Nevertheless, the underlying logic that motivated previous agreements — namely, that mutual restraint can serve the security interests of all parties — retains its essential validity. Whether this logic can find expression in new frameworks suited to contemporary conditions remains a fundamental question.", question: "Which proposition does the passage advance most directly?", options: ["Arms control is a relic of the Cold War era with little practical applicability to today's contemporary security environment.", "The principle motivating earlier arms control remains relevant even where specific agreements have failed.", "Emerging technologies have rendered the entire concept of strategic stability functionally obsolete in the present moment.", "Hypersonic weapons should be the immediate focus of any new arms control negotiations between the major powers."], answer: 1, ex: "'The underlying logic... retains its essential validity. Whether this logic can find expression in new frameworks suited to contemporary conditions remains a fundamental question' — Option B captures the distinction between the validity of the principle and the difficulty of its implementation. A directly contradicts this. C contradicts 'underlying logic retains validity'. D is over-specific and not advanced as the passage's main argument. Level 4 requires distinguishing the abstract principle from its concrete instantiations." },
    { topic: "Civilian harm mitigation", passage: "The mitigation of civilian harm in armed conflict has emerged as a central concern in contemporary military operations, reflecting evolving legal obligations, strategic imperatives, and ethical commitments. Modern doctrine recognises that the protection of civilians is not merely a legal constraint upon military action but a strategic objective in its own right. Civilian casualties undermine the legitimacy of operations, alienate populations whose cooperation may be essential to mission success, and provide propaganda advantages to adversaries. Implementation of robust mitigation requires investment in intelligence, surveillance, and precision capabilities, alongside training, doctrine, and accountability mechanisms. These investments compete with other priorities in resource-constrained environments. Critics argue that despite improvements, the gap between stated commitments and operational reality remains substantial, particularly in operations conducted by partner forces with less developed protection cultures.", question: "What conceptual shift in the treatment of civilian harm does the passage identify?", options: ["Civilian harm has been redefined as a propaganda concern rather than a binding legal issue under international law.", "Mitigation has become essentially impossible in modern conflict due to severe budgetary and resource constraints.", "Protection of civilians has moved from being a legal restriction to also being an operational goal.", "Partner forces have replaced alliance forces as the primary source of civilian casualties in recent campaigns abroad."], answer: 2, ex: "'Not merely a legal constraint upon military action but a strategic objective in its own right' — option C paraphrases this as moving from 'legal restriction' to 'also being an operational goal'. The key word is 'not merely... but also' — both remain true. A is wrong because legal status is preserved, not replaced. B and D overstate. Level 4 distinguishes 'addition of a new framing' from 'replacement of the old one'." },
    { topic: "Resilience", passage: "Resilience has emerged as a central concept in contemporary security thinking, reflecting recognition that prevention of all hostile actions is impossible and that the capacity to absorb, adapt to, and recover from hostile actions is therefore essential. Alliance doctrine identifies seven baseline resilience requirements covering critical infrastructure, civilian capabilities, and continuity of government. Implementation depends primarily upon national authorities, although coordination through alliance mechanisms enhances coherence and identifies gaps. Resilience requirements interact with traditional military capabilities in complex ways. Investments in resilience may reduce vulnerabilities that adversaries seek to exploit, thereby contributing to deterrence by denial. Conversely, evident gaps may incentivise hostile action by suggesting attractive targets. The conceptual challenge lies in calibrating resilience investments appropriately, given that absolute resilience is unattainable and excessive defensive measures may impose unsustainable costs on civilian society.", question: "What paradox in the relationship between resilience and adversary behaviour does the passage highlight?", options: ["Resilience investments are most effective when concealed from potential adversaries before any conflict begins.", "Resilience measures only work when complemented by sufficient offensive capabilities held in reserve.", "Civilian and military resilience requirements are fundamentally incompatible and cannot be coordinated effectively.", "The same investments that discourage attack can also signal where vulnerabilities lie."], answer: 3, ex: "Resilience investments 'may reduce vulnerabilities... thereby contributing to deterrence by denial. Conversely, evident gaps may incentivise hostile action by suggesting attractive targets'. The paradox: resilience can both deter (by removing targets) and invite (by revealing remaining gaps). Option D captures this dual signalling effect. A, B, C are unrelated. Level 4 demands identifying paradoxical/dialectical relationships within a passage." },
    { topic: "Burden sharing", passage: "Burden sharing within the alliance has been a perennial source of contention, but the debate has acquired new intensity in the contemporary period. The benchmark of two percent of gross domestic product, agreed at the Wales Summit, has become a politically charged metric despite its acknowledged limitations as a measure of meaningful contribution. Defence spending alone captures neither the quality of capabilities developed nor the operational contributions made by member states. A nation might exceed the spending threshold while investing inefficiently in capabilities of marginal alliance utility, while another might fall below the threshold yet provide highly capable forces in critical operations. More sophisticated assessments incorporate measures of capability development, operational deployment, and acceptance of risk in alliance missions. Yet the simplicity of the spending metric ensures its continued political prominence, even as analysts debate whether the underlying rationale is best served by alternative frameworks.", question: "Why does the spending metric persist despite its analytical weaknesses?", options: ["Its accessibility as a single number makes it useful in political discourse.", "Member states have formally agreed not to use any more sophisticated alternatives.", "Analysts have so far failed to develop credible alternative measures of contribution.", "Alliance treaties currently require its use as the sole measure of national contribution."], answer: 0, ex: "'The simplicity of the spending metric ensures its continued political prominence' — option A paraphrases 'simplicity' and 'political prominence' as 'accessibility as a single number' and 'useful in political discourse'. B is contradicted. C is contradicted ('more sophisticated assessments' exist). D is fabricated. Level 4: recognising that 'political prominence' implies utility for political actors, not analytical merit." },
    { topic: "Maritime domain awareness in contested waters", passage: "The proliferation of grey-zone activities in maritime contested waters has substantially complicated the practice of maritime domain awareness. Traditional surveillance frameworks, predicated upon binary distinctions between military and civilian vessels, prove inadequate against actors who deliberately employ ostensibly civilian platforms for purposes that are functionally military in character. Fishing fleets operating under state direction, research vessels conducting ambiguous activities near sensitive infrastructure, and commercial shipping deployed in patterns suggesting reconnaissance all defy categorical responses. Effective awareness now requires fusion of automatic identification system data, satellite imagery, behavioural pattern analysis, and contextual intelligence. Yet the resulting analytical product carries irreducible uncertainty, since intent cannot be reliably inferred from observable behaviour alone. Decision-makers must consequently act on probabilistic assessments rather than definitive determinations. The temptation to demand greater certainty before acting frequently proves counterproductive, since the operational tempo of grey-zone activities exploits precisely such hesitation. Conversely, acting on insufficient evidence risks both diplomatic costs and the erosion of analytical credibility upon which future warnings depend.", question: "What does the passage identify as a fundamental analytical limitation in contemporary maritime domain awareness?", options: ["Insufficient satellite coverage of contested waters", "Inability to reliably infer intent from observable behaviour", "Lack of cooperation between civilian and military authorities", "Outdated automatic identification system technology"], answer: 1, ex: "'intent cannot be reliably inferred from observable behaviour alone' — option B paraphrases this directly. A は技術的問題として誤認させる distractor。C は組織的問題、D は機材の老朽化として誤誘導。Level 4 では「観察可能な行動」と「内在する意図」の認識論的ギャップを理解できるかが問われる。" },
    { topic: "Quantum technology strategic implications", passage: "The strategic implications of quantum technology development extend well beyond the much-discussed prospect of cryptographic vulnerability. Quantum sensing offers detection capabilities for objects and phenomena previously beyond observational reach, with potentially transformative consequences for submarine warfare, underground facility detection, and inertial navigation independent of satellite signals. Quantum communications promise theoretically secure channels resistant to interception by any technological means. The maturation timelines for these capabilities remain genuinely uncertain, with serious experts offering estimates differing by decades. This uncertainty itself carries strategic significance, since planning assumptions calibrated to optimistic timelines risk wasted investment, while assumptions calibrated to pessimistic ones risk strategic surprise. The tendency to focus public discussion on cryptographic threats reflects partly their conceptual accessibility relative to other quantum applications. Yet the cryptographic challenge admits relatively well-understood mitigation pathways through algorithmic transition, whereas the operational implications of quantum sensing in particular may prove more disruptive precisely because countermeasures remain conceptually undefined.", question: "What does the passage suggest about quantum sensing relative to cryptographic threats?", options: ["Quantum sensing has been adequately addressed by current research investment", "Cryptographic threats are more strategically significant than sensing threats", "Quantum sensing may prove more disruptive due to undefined countermeasures", "Both threats can be addressed through broadly similar mitigation pathways"], answer: 2, ex: "'the operational implications of quantum sensing in particular may prove more disruptive precisely because countermeasures remain conceptually undefined' — option C はこの主張を直接反映。A は「対処済み」として正反対、B は cryptographic を過大評価する誤誘導 (passage は逆を示唆)、D は両者を同列に扱う誤り。Level 4 はこのような「公開議論の焦点」と「実際の戦略的重要度」の差異を読み解く力を試す。" },
    { topic: "Climate-induced migration security challenges", passage: "The securitisation of climate-induced migration represents both an analytical advance and a conceptual hazard. Recognition that environmental disruption generates population movements with potential security implications has appropriately broadened the scope of contingency planning. Yet framing migration primarily through a security lens carries risks that frequently go unacknowledged in operational discourse. Such framing can transform vulnerable populations into objects of suspicion rather than subjects of protection, shape institutional responses toward containment rather than support, and obscure the political and economic factors that interact with environmental drivers to produce displacement. Empirical evidence suggests that climate variables seldom act as monocausal drivers of large-scale migration, instead interacting with governance failures, economic conditions, and social networks in ways that resist deterministic prediction. Security planning calibrated to alarmist projections risks misallocating resources toward improbable mass movements while underinvesting in the more probable patterns of incremental, localised displacement that nonetheless aggregate to significant cumulative effects.", question: "What does the passage identify as a risk of viewing climate-induced migration primarily through a security lens?", options: ["It overstates climate's role as the single decisive cause of the population movement", "It diverts attention from cryptographic and information-infrastructure vulnerabilities", "It encourages an excessive degree of cooperation with humanitarian agencies in transit countries", "It transforms vulnerable populations into objects of suspicion rather than protection"], answer: 3, ex: "'Such framing can transform vulnerable populations into objects of suspicion rather than subjects of protection' — option D はこの記述を直接反映。A は別の主張 (climate as monocausal driver) で混同を狙う。C は他テーマからの distractor、D は本文と矛盾。Level 4 は「安全保障の枠組み化」がもたらす道徳的・実務的副作用を識別する力を試す。" },
    { topic: "Artificial intelligence ethics in military targeting", passage: "The integration of artificial intelligence into military targeting decisions raises ethical questions whose practical resolution lags substantially behind technical capabilities. Proponents emphasise potential improvements in discrimination and proportionality through enhanced data integration and reduced human cognitive limitations under stress. Critics counter that automation introduces new failure modes whose consequences fall disproportionately upon those least able to contest them. Both positions contain merit, and resolution requires neither uncritical adoption nor categorical prohibition but rather the cultivation of meaningful human control across decision sequences whose distributed character resists simple human-in-the-loop characterisations. The challenge is not principally technological but institutional, requiring procedures that preserve genuine human agency rather than ritualistic confirmation of algorithmic recommendations. Existing accountability frameworks, designed for clearly attributable individual decisions, prove inadequate for distributed sociotechnical systems where outcomes emerge from interactions between human judgement, algorithmic processing, and operational pressures. Developing accountability mechanisms suited to these realities represents a more pressing requirement than continued technical refinement of underlying capabilities.", question: "What does the passage identify as a more pressing requirement than continued technical refinement?", options: ["Developing accountability mechanisms suited to distributed sociotechnical systems", "A categorical prohibition of all military AI applications, regardless of context or oversight", "Faster algorithmic processing of targeting data under contested electromagnetic conditions", "Reducing human involvement in targeting decisions in order to improve operational tempo"], answer: 0, ex: "'Developing accountability mechanisms suited to these realities represents a more pressing requirement than continued technical refinement' — option A はこの主張を直接反映。A は批判者の極端版として誤誘導、B は技術改善という passage が拒否する優先順位、D は人間統制の弱体化として本文と正反対。Level 4 では「技術 vs 制度」の優先順位判断を読み取る力を試す。" },
    { topic: "Critical mineral supply chain vulnerabilities", passage: "Critical mineral supply chains constitute a strategic vulnerability whose mitigation has proved unexpectedly difficult despite sustained policy attention. The geographic concentration of extraction and, more acutely, of intermediate processing reflects decades of investment patterns that cannot be readily reversed. Substitution research has produced incremental rather than transformative results, since the properties of certain elements prove difficult to replicate through alternative materials. Recycling offers genuine but bounded contributions, since current end-of-life flows for many critical minerals remain modest relative to demand growth. Stockpiling provides operational reassurance but at significant fiscal cost and without addressing structural dependence. Diversification of supply requires sustained capital investment under conditions of price volatility that discourage precisely such investment from market actors operating on commercial timeframes. Resolution accordingly requires sustained governmental engagement that runs counter to prevailing assumptions about appropriate boundaries between public and private economic activity, generating political controversies that further complicate already difficult technical and commercial challenges.", question: "What does the passage identify as discouraging private market investment in supply diversification?", options: ["Insufficient consumer demand for diversified supplies", "Price volatility under commercial timeframes", "Government overregulation of mineral markets", "Excessive recycling capacity in current systems"], answer: 1, ex: "'sustained capital investment under conditions of price volatility that discourage precisely such investment from market actors operating on commercial timeframes' — option B はこの理由を直接反映。A は需要要因として誤誘導、C は規制過多として正反対 (passage は政府関与不足を示唆)、D は recycling との混同。Level 4 では「市場の論理」と「戦略的必要性」の構造的ミスマッチを読み解く力を試す。" }
  ],
};
